window.POEM_DB=window.POEM_DB||{};POEM_DB["song_040"]={"n":"张镃","dyn":"宋","poems":[{"t":"许道士房","f":"七言绝句","c":["凉蝉乱叫朝暮雨，独鹤不迷前后山。","芎叶煮汤胜茗椀，栗花然火称松关。"]},{"t":"南柯子/南歌子","f":"词","c":["积雪迷松径，围炉掩竹扉。","床头一味有蹲鸱。","软火深开香熟、已多时。","自得陶朱法，休教懒瓒知。","浪传黄独正甘肥。","紫玉婴儿盈尺、更新奇。"]},{"t":"昭君怨 园池夜汎","f":"词","c":["月在碧虚中住。","人向乱荷中去。","花气杂风凉。","满船香。","云被歌声摇动。","酒被诗情掇送。","醉里卧花心。","拥红衾。"]},{"t":"菩萨蛮 芭蕉","f":"词","c":["风流不把花为主。","多情管定烟和雨。","潇洒绿衣长。","满身无限凉。","文笺舒卷处。","似索题诗句。","莫凭小阑干。","月明生夜寒。"]},{"t":"丁未立春","f":"七言绝句","c":["今岁春从底处回，非关缇室动葭灰。","幽人昨夜池塘梦，已见新春草际来。"]},{"t":"七夕口占","f":"七言绝句","c":["凉生金井未飘桐，月户星楼记古风。","乞巧频年但成拙，懒将祈请效儿童。"]},{"t":"七夕池上泛舟四首 其四","f":"七言绝句","c":["夜雨连明旋出奇，涨平荷盖失参差。","更教红莟肩齐水，要学湘妃晓浴时。"]},{"t":"七夕池上泛舟四首 其三","f":"七言绝句","c":["柳系荃桡句未成，拨船微动碧香迎。","琉璃自爱无瑕翳，不放池西一叶生。"]},{"t":"七夕池上泛舟四首 其二","f":"七言绝句","c":["秋入冯夷碧殿凉，仙游十万不分行。","锦蜺香满烟蒙伞，翠凤光浮露涤裳。"]},{"t":"七夕池上泛舟四首 其一","f":"七言绝句","c":["居士乘閒养就痴，争如灵鹊自知时。","不从楼上求新巧，却向船中赋拙诗。"]},{"t":"九日","f":"七言绝句","c":["重阳冷菊青黄蕊，半醉幽人黑白头。","今岁有番堪恨处，病无诗句过中秋。"]},{"t":"三月望日微雨汎舟西湖四首 其四","f":"七言绝句","c":["堤树枝条老更成，岂容他处夏阴清。","东风不惜吹芳草，绿满鹅儿燕子情。"]},{"t":"三月望日微雨汎舟西湖四首 其三","f":"七言绝句","c":["倭缬帘垂柳外楼，靓妆微露玉搔头。","承平气象应如此，忆杀金明水殿游。"]},{"t":"三月望日微雨汎舟西湖四首 其二","f":"七言绝句","c":["非是天悭一日晴，晦明多态属诗人。","云翻画样烘濛墨，波捲纹头起突银。"]},{"t":"三月望日微雨汎舟西湖四首 其一","f":"七言绝句","c":["清明才过雨连风，着色湖山便面中。","草上踏青人自出，舣船无地不飞红。"]},{"t":"山行","f":"七言绝句","c":["鸟飞不过人行处，山好直连天尽头。","下马忽逢难画景，溜声戛玉亦销忧。"]},{"t":"山堂","f":"七言绝句","c":["芒鞋疏到笋篱东，惯得苍苔把径封。","已愧君诗足真味，尚将鸡肋较驼峰。"]},{"t":"书北厅后檐壁","f":"七言绝句","c":["重阳过后雨垂垂，病怯新寒独立时。","菊有万株归未得，一窗来此看花枝。"]},{"t":"书叶轩 其二","f":"七言绝句","c":["正是桐阴雨乍晴，隔笼黄鸟女儿声。","笔床经笥閒家具，物物皆从我太平。"]},{"t":"书叶轩 其一","f":"七言绝句","c":["当处心安即洞天，黄连一炷胜龙涎。","閒房幸自无人到，谁放白云来枕前。"]},{"t":"书苍寒堂壁二首 其二","f":"七言绝句","c":["一灯清坐欲三更，月到疏棂胧松明。","除了当栏松上鹊，无人听得读书声。"]},{"t":"书苍寒堂壁二首 其一","f":"七言绝句","c":["隔竹红梅酷似桃，政宜修涧绿周遭。","武陵风景何时别，不绝人来意更高。"]},{"t":"云露堂","f":"七言绝句","c":["种玉栽琼树树匀，主人心地况长春。","便教不假云间路，亦有芳菲日日新。"]},{"t":"五家林四首 其四","f":"七言绝句","c":["散乱飞鸿掠快晴，嗈嗈那复苦寒声。","定知已入新诗了，才过余舟便不鸣。"]},{"t":"五家林四首 其三","f":"七言绝句","c":["草木敷荣怕入秋，霜天却自不穷愁。","弹丸都把黄金铸，乱挂枯疏冻树头。"]},{"t":"五家林四首 其二","f":"七言绝句","c":["岸转欣逢撇撇儿，蹙成千步响琉璃。","没波岂但寻鱼吃，水不能濡只我知。"]},{"t":"五家林四首 其一","f":"七言绝句","c":["放鸭成群趁暖晖，村童遮护只狂飞。","多多益办真难事，半里撑船赶不归。"]},{"t":"从张子立觅驴二绝 其二","f":"七言绝句","c":["几回曾许借侬骑，兴到牵来已早迟。","乞与南湖了幽事，白裘乌帽要相宜。"]},{"t":"从张子立觅驴二绝 其一","f":"七言绝句","c":["蹇驴休爱鸽毛青，指日骅骝辇路行。","听水听松方属我，灞桥风雪可寒盟。"]},{"t":"以桂隐樱桃从益之博红酒诗","f":"七言绝句","c":["闻道君家琥珀霞，杭州那更说梨花。","樱桃颗颗堪持比，换取一尊来水涯。"]},{"t":"分韵赋散水花得盐字 其一","f":"七言绝句","c":["春皇游骑玉垂鞭，珠捲扬州十里帘。","一笑诗成休浪举，花如西子句无盐。"]},{"t":"分韵赋散水花得盐字 其二","f":"七言绝句","c":["盈枝点缀雪花鲜，环映清流分外妍。","应是东君归骑速，不如坠下玉丝鞭。"]},{"t":"分韵赋散水花得盐字 其三","f":"七言绝句","c":["苔径斜通砌竹鞭，素光交映入湘帘。","若教谢女庭前种，不道空中雪似盐。"]},{"t":"分题得古木","f":"七言绝句","c":["穴处曾经起怒雷，断藤枯藓半离披。","根茎托土何妨远，会见春风长活枝。"]},{"t":"壬寅立春 其一","f":"七言绝句","c":["经旬寒雨正霖霪，才转东风便肯晴。","我自西畴心念熟，不须学稼始归耕。"]},{"t":"壬寅立春 其二","f":"七言绝句","c":["蓼醯蔬饼媚晨羞，一饱宁知老到头。","但听儿童语声喜，黑头青角看泥牛。"]},{"t":"天声馆","f":"五言绝句","c":["鸾鹤纷来下，天风驾月明。","语言难道断，不堕世间声。"]},{"t":"忆南湖","f":"七言绝句","c":["暖云台观绕歌弦，花底吹香翠鬓船。","闹处如今浑懒去，可能心绪数年前。"]},{"t":"忆夏墟山园","f":"七言绝句","c":["松处筑亭何日见，霜时开径去年行。","速排忙事成幽事，已觉贪山浪得声。"]},{"t":"方壶","f":"七言绝句","c":["春在壶中晚更长，众仙相命醉霓觞。","戏将龙脑真珠网，搭上周回碧玉廊。"]},{"t":"水边","f":"七言绝句","c":["翠藤萦树夕花明，无数圆荷贴乱萍。","酒力半销来照影，晚风轻澹鹤梳翎。"]},{"t":"水栀 其二","f":"七言绝句","c":["汲水埋盆便当池，水栀花旺雪盈枝。","江湖万里何曾远，祗在先生托兴时。"]},{"t":"水栀 其一","f":"七言绝句","c":["拳石泓泉媚浅沙，孤根蟠窟养清华。","细看六出瑶英小，薝卜分明是雪花。"]},{"t":"水阁即事二首 其二","f":"七言绝句","c":["今岁春来我亦来，折花犹未见花开。","新春况有四十日，莫怪幽人空手回。"]},{"t":"水阁即事二首 其一","f":"七言绝句","c":["水阁开窗景不偏，断桥堤柳尽横前。","平生到处居人后，已有貂珰泊画船。"]},{"t":"水蕉","f":"七言绝句","c":["笼丛旧爱溪边树，路转清风尽日阴。","窗下不生分别相，石盆秋水养蕉林。"]},{"t":"王倅德远有诗谢送菊因酬二绝 其二","f":"七言绝句","c":["爱竹君家有子猷，黄花君复向人求。","不妨官事兼幽事，应笑侬归两过秋。"]},{"t":"车中闻人说溪涧如水晶色口占一绝","f":"七言绝句","c":["涧水流如活水晶，道傍一语唤人醒。","山林未必渠能说，说著山林便可听。"]},{"t":"写扇","f":"七言绝句","c":["世间功业任差殊，心地明时自有馀。","若道必从勤学得，当年稷卨读何书。"]},{"t":"出城二首 其二","f":"七言绝句","c":["扁舟初上一声雷，两岸浓云乱欲堆。","堪笑此时晴太早，篷遮未定雨先来。"]},{"t":"出城二首 其一","f":"七言绝句","c":["只道南湖没样奇，出关又有许多诗。","便须抄取天然句，才下工夫走却伊。"]},{"t":"四月上浣日同寮约游西湖十绝 其九","f":"七言绝句","c":["寮寀招邀胜引多，旷怀真语当弦歌。","联翩逸驾知难及，乞我扁舟著钓蓑。"]},{"t":"四月上浣日同寮约游西湖十绝 其五","f":"七言绝句","c":["赐沐山行策最长，游人此日却相妨。","洞天只得东边赏，开过灯花断杀肠。"]},{"t":"四月上浣日同寮约游西湖十绝 其四","f":"七言绝句","c":["饭馀飞盖北山来，上苑虚堂柳际开。","系马林间宁复散，却容拄杖卓青苔。"]},{"t":"四月上浣日同寮约游西湖十绝 其一","f":"七言绝句","c":["自得城隅水北居，西湖幽讨句全疏。","今朝掩簿抽身出，更向谁边不一书。"]},{"t":"四月上浣日同寮约游西湖十绝 其三","f":"七言绝句","c":["卖龟船小样漪涟，折得蘋花亦当钱。","我自沧洲隔三载，此花风调只依然。"]},{"t":"四月上浣日同寮约游西湖十绝 其六","f":"七言绝句","c":["夹堤全少露桃红，独许垂杨翠拂空。","千古苏仙几曾死，骑鲸时或下亭中。"]},{"t":"四月上浣日同寮约游西湖十绝 其七","f":"七言绝句","c":["茭葑茸茸展翠毡，六桥分舞燕翎纤。","撑船捷出苍湾去，要看山围玉镜奁。"]},{"t":"四月上浣日同寮约游西湖十绝 其十","f":"七言绝句","c":["丰乐楼前未夕晖，可堪鱼钥限城扉。","诗成快向归时写，丹墨明朝与兴违。"]},{"t":"四月上浣日同寮约游西湖十绝 其八","f":"七言绝句","c":["喜逐刍荛禁苑东，舜弦调处剩薰风。","戎葵学得宫衣缬，不作人间锦样红。"]},{"t":"四月上浣日同寮约游西湖十绝 其二","f":"七言绝句","c":["清晓溟濛雨气浓，出关晴色便葱茏。","层云特为诗人喜，添起山头四五峰。"]},{"t":"正月初四日听新乐成绝句 其二","f":"七言绝句","c":["治音安乐绍熙初，试听咸韶可并驱。","鼗武磬襄奚足数，作成从此不愁无。"]},{"t":"正月初四日听新乐成绝句 其一","f":"七言绝句","c":["鳌抃钧天沸广场，渡江何翅纪铿锵。","频年遏密无悰绪，乐叟閒来说泰皇。"]},{"t":"玉照东西两轩有红梅及千叶缃梅未经题咏倒用前韵各赋五首 其五","f":"七言绝句","c":["方诸台耸日边云，望拜青童上相君。","侍女百千皆绛服，恰如檐外树纷纷。"]},{"t":"玉照东西两轩有红梅及千叶缃梅未经题咏倒用前韵各赋五首 其四","f":"七言绝句","c":["海棠曾把比朝眠，妃子妆慵玉镜前。","若似此花颜色好，定教天宝画师传。"]},{"t":"玉照东西两轩有红梅及千叶缃梅未经题咏倒用前韵各赋五首 其三","f":"七言绝句","c":["一粒丹砂换骨来，移根闻自浙东栽。","市门古巷留遗迹，问讯仙翁定姓梅。"]},{"t":"玉照东西两轩有红梅及千叶缃梅未经题咏倒用前韵各赋五首 其二","f":"七言绝句","c":["虽嫌绿叶与青枝，入格依前自欠诗。","几向斜阳溪畔见，犹将桃杏误猜疑。"]},{"t":"玉照东西两轩有红梅及千叶缃梅未经题咏倒用前韵各赋五首 其一","f":"七言绝句","c":["昔游尝到海中光，我与诸公各醉狂。","同向尘中三十载，朱颜应笑鬓丝长。"]},{"t":"玉照堂次韵茂洪古梅","f":"七言绝句","c":["天教萼绿伴羊权，羞对尘颜粉黛妍。","不必修真事灵诀，与花端合共长年。"]},{"t":"玉照堂观梅二十首 其二十","f":"七言绝句","c":["高窠依约百年馀，蠹蘖重重艾衲铺。","亲见主人来买地，遮番添得白髭须。"]},{"t":"玉照堂观梅二十首 其十九","f":"七言绝句","c":["风调花常逐岁新，苦惭诗思只陈陈。","吟成不敢分明举，生怕渠知鄙薄人。"]},{"t":"玉照堂观梅二十首 其十八","f":"七言绝句","c":["杯行才到莫留残，要向梅边露肺肝。","今日正晴还有雪，谓予不信试遥看。"]},{"t":"玉照堂观梅二十首 其十七","f":"七言绝句","c":["喜客能挥白玉琴，此花端解古时音。","只防老鹤来偷听，引起翻云万里心。"]},{"t":"玉照堂观梅二十首 其十六","f":"七言绝句","c":["今夕悬知月未圆，照梅已自不胜妍。","冰姿玉色谁堪比，除是姮娥敢并肩。"]},{"t":"玉照堂观梅二十首 其十五","f":"七言绝句","c":["九节筇枝休化龙，佳时朝暮且相从。","枯条岂但敲令尽，鸟雀冲花定不忪。"]},{"t":"玉照堂观梅二十首 其十四","f":"七言绝句","c":["苍帝妃嫔总素装，胜游常是遍江乡。","玉楼谪堕迟归去，冷淡工夫笑我忙。"]},{"t":"玉照堂观梅二十首 其十三","f":"七言绝句","c":["鹎鵊呼人晓梦回，霁光催赏百株梅。","轻车不管沾泥滑，童子从来自惯推。"]},{"t":"玉照堂观梅二十首 其十二","f":"七言绝句","c":["正煖休嫌夜雨来，恐花乘煖一齐开。","不然何事东风意，容易吹香与碧苔。"]},{"t":"玉照堂观梅二十首 其十一","f":"七言绝句","c":["萧然日月岸纶巾，春满幽园肯倦行。","一事尚须烦造物，看松微雨看梅晴。"]},{"t":"玉照堂观梅二十首 其十","f":"七言绝句","c":["别开庭院近莲塘，油榭栏干小扇窗。","更取梅花瓶内插，放教清梦月横江。"]},{"t":"玉照堂观梅二十首 其九","f":"七言绝句","c":["山际楼台水际村，见梅常是动吟魂。","全身此日清芬里，篱落疏斜不喜论。"]},{"t":"玉照堂观梅二十首 其八","f":"七言绝句","c":["醉上轻舟泛渌漪，细穿桥柱独行迟。","风前抚掌催花发，惊起群飞五色儿。"]},{"t":"玉照堂观梅二十首 其六","f":"七言绝句","c":["六日新春一再来，直须登树赏花开。","攀翻径上枝梢外，不负东风是此杯。"]},{"t":"玉照堂观梅二十首 其五","f":"七言绝句","c":["群芳非是乏新奇，或在繁时或嫩时。","唯有南枝香共色，从初到底绝瑕疵。"]},{"t":"玉照堂观梅二十首 其四","f":"七言绝句","c":["纵横遥衬碧云端，林下铺毡坐卧看。","不但归家因桂好，为梅亦合早休官。"]},{"t":"玉照堂观梅二十首 其三","f":"七言绝句","c":["生怕高花易过春，隔年先早著精神。","冰绡旋买连三幅，剩与溪山并写真。"]},{"t":"玉照堂观梅二十首 其二","f":"七言绝句","c":["映竹依松望最宜，如无似有乍开时。","思量切比幽人语，不著工夫格自奇。"]},{"t":"玉照堂观梅二十首 其一","f":"七言绝句","c":["一笑林间说向春，宿缘三世岂无因。","半生忧患摧残损，却与梅花作主人。"]},{"t":"玉照堂观梅二十首 其七","f":"七言绝句","c":["从来嫌用和羹字，才到诗中俗杀人。","一片彩云溪上暖，兴随芳草夕阳新。"]},{"t":"玉照堂梅花飘落如雪","f":"七言绝句","c":["阵阵翻空回旋飞，缀巾沾袖却横吹。","东风秘授看花诀，不在开时在落时。"]},{"t":"甲辰仲冬八日元衡携两诗过访及归次韵酬送后篇兼寄张武子 其一","f":"七言绝句","c":["每将幽事当功名，唯欠能诗竹里僧。","径写此篇为疏引，庵成来往岂无凭。"]},{"t":"甲辰仲冬八日元衡携两诗过访及归次韵酬送后篇兼寄张武子 其二","f":"七言绝句","c":["合处畴能證不疑，吾宗神秀岁寒姿。","无书寄便今犹懒，说似应须倩老师。"]},{"t":"白头翁鸟","f":"七言绝句","c":["桧丛幽啭惬新晴，巧好春林百鸟声。","羽辈误教推皓首，细听多是少年情。"]},{"t":"白杨梅","f":"七言绝句","c":["兴高团雪缀珍丛，弹火烧林一洗空。","驿骑不供妃子笑，冰姿犹胜荔枝红。"]},{"t":"石门小泊","f":"七言绝句","c":["近村非少茂林枝，十二乌巢一树栖。","应恐此间难觅句，预先留作我诗题。"]},{"t":"立秋后一日池上杂兴 其四","f":"七言绝句","c":["冰轮艳艳涌东墙，鱼触波纹破碎光。","十万人家眠正熟，谁知凉满一胡床。"]},{"t":"立秋后一日池上杂兴 其一","f":"七言绝句","c":["渔舟閒上揭疏篷，倚遍苕华岸岸红。","两日新秋凉便觉，费人诗句是西风。"]},{"t":"立秋后一日池上杂兴 其二","f":"七言绝句","c":["船舷何事若轻雷，荡叶冲莲一道开。","莫待归时方命酒，径从花上递金杯。"]},{"t":"立秋后一日池上杂兴 其三","f":"七言绝句","c":["小娃犹记喜归时，故唱前年自赋词。","但得池边鸥鹭听，更须门外野人知。"]},{"t":"记雪三首 其三","f":"七言绝句","c":["无月无灯夜自明，模糊何啻瓦沟平。","不拖藜杖高桥去，那得金龙背上行。"]},{"t":"记雪三首 其二","f":"七言绝句","c":["直教日色避寒光，世界移来玉海藏。","何事连年无此景，老天游戏不循常。"]},{"t":"记雪三首 其一","f":"七言绝句","c":["清晓疏篱尚露根，饭馀俄复拥柴门。","南湖水色君知否，万斛鹅黄贮玉盆。"]},{"t":"龙井山主送腊梅","f":"七言绝句","c":["风落松钗满涧桥，野蜂移蜜上枯条。","道人参得山中语，不是涂黄一样娇。"]},{"t":"龙瑞宫","f":"七言绝句","c":["阳明古罅閟灵宫，祷雨传闻见活龙。","可是高人不留我，却从归路数杉松。"]},{"t":"任道源转示玉艳亭探梅诗卷未暇属和闰月十一日偶自北山塔院过亭下枝间已花因次元韵三首 其三","f":"七言绝句","c":["占断林家一种春，隔湖茅舍羡渔人。","折枝弄蕊年年手，生怕长安揖马尘。"]},{"t":"任道源转示玉艳亭探梅诗卷未暇属和闰月十一日偶自北山塔院过亭下枝间已花因次元韵三首 其二","f":"七言绝句","c":["细看孤标迎腊瘦，争如繁艳遇春酣。","古来节士功名薄，剩欲裁诗问水南。"]},{"t":"任道源转示玉艳亭探梅诗卷未暇属和闰月十一日偶自北山塔院过亭下枝间已花因次元韵三首 其一","f":"七言绝句","c":["因花不作等閒来，屐印苔纹酒便回。","明日窗前追昨梦，似逢姑射不逢梅。"]},{"t":"过莺脰湖","f":"五言绝句","c":["晓雾濛鸿合，山藏岸绝痕。","浩波吞日去，金晃玉乾坤。"]},{"t":"再游 其二","f":"七言绝句","c":["天风吹我落人间，暂入青山又促还。","待得霜林收柿栗，却来重扣白云关。"]},{"t":"同王梦得夜坐","f":"五言绝句","c":["何处起香云，清谈我与君。","雨来临水坐，鱼跃隔窗闻。"]},{"t":"回至泰阳村得家信二首 其二","f":"七言绝句","c":["桂隐闻知得雨来，榴花应对竹光开。","归家早见南湖月，饮水犹胜举酒杯。"]},{"t":"回至泰阳村得家信二首 其一","f":"七言绝句","c":["乾鹊飞鸣绕路隅，长须迎望果持书。","鸡豚本自无烦饷，七日山行惯食蔬。"]},{"t":"夙兴","f":"七言绝句","c":["霜池微带月痕斜，风竹声如撒细沙。","坐到晓窗尤可爱，只愁烘损腊梅花。"]},{"t":"安溪道中","f":"七言绝句","c":["染晴波色重于蓝，烟坞人家屋两三。","明月在山天在水，后回休睡泊溪南。"]},{"t":"寻桂南山至崇寿院因往灵石三首 其三","f":"七言绝句","c":["山头藤断空垂子，亭下泉荒不满池。","老衲坐来知敬客，南音犹记鬼仙诗。"]},{"t":"寻桂南山至崇寿院因往灵石三首 其二","f":"七言绝句","c":["迎客山僧未下廊，好风吹鼻便生狂。","莫疑佛宇清芬烈，薝卜曼殊共借香。"]},{"t":"寻桂南山至崇寿院因往灵石三首 其一","f":"七言绝句","c":["折枝登几已孤妍，况值风林水石边。","荦确路斜飞盖歇，丁宁茅店略停烟。"]},{"t":"寻梅三首 其三","f":"七言绝句","c":["韩园邂逅一来寻，还忆朱栏小院深。","相对两亭无四壁，定参陶令不弦琴。"]},{"t":"寻梅三首 其二","f":"七言绝句","c":["柴界墙头蜂未窥，草烟沙径亦空枝。","要知愁结吹香晚，铁石心肠欠我诗。"]},{"t":"寻梅三首 其一","f":"七言绝句","c":["绀碧烘晴水照天，断槎荒葑牧羝田。","数旬不踏苏堤路，专为梅花跨晓鞯。"]},{"t":"尖檐帽","f":"七言绝句","c":["落魄青楼倒接䍦，醉花争插乱红欹。","如今两垫纶巾角，汝帽尖新却自宜。"]},{"t":"岁旦立春 其四","f":"七言绝句","c":["从此车书看混同，王春丕建四时功。","八千岂但庄椿比，宸极光符万岁中。"]},{"t":"岁旦立春 其六","f":"七言绝句","c":["结宇城隅野老同，只将歌咏纪元功。","枯荄亦喜春回早，为在条风振拂中。"]},{"t":"岁旦立春 其一","f":"七言绝句","c":["天心历数本相同，何事偏窥造化功。","苍震欲承乾健力，岁端春肇一时中。"]},{"t":"岁旦立春 其三","f":"七言绝句","c":["赞美平时万口同，耸观造化协天功。","圣朝家法皆仁德，宽大应符帝诏中。"]},{"t":"岁旦立春 其二","f":"七言绝句","c":["授受须知道一同，机缄默运仰神功。","重轮赫日当天照，万国阳和淑气中。"]},{"t":"岁旦立春 其五","f":"七言绝句","c":["宝翰钟王妙与同，虎龙腾跃更新功。","诗成秦观如佳兆，适契青宫得意中。"]},{"t":"戏仿韩致光体","f":"七言绝句","c":["意懒风前侧帽檐，落梅红在麦修纤。","归家说尽单行处，可奈温香翡翠奁。"]},{"t":"戏成白发二首 其二","f":"五言绝句","c":["朝朝摘白发，新生亦非黑。","纵使白不生，秃翁还讳得。"]},{"t":"戏成白发二首 其一","f":"五言绝句","c":["怕见人言老，梳头夜二更。","谁知灯烛夜，漏逗愈分明。"]},{"t":"戏咏咸蛤","f":"七言绝句","c":["盐作栖巢涕作脂，樽前风味不胜低。","纵教一衲被云水，无奈胸中著淤泥。"]},{"t":"戏答客问","f":"五言绝句","c":["桂隐芙蓉盛，柴门日日开。","若无诗与酒，不请看花来。"]},{"t":"戏题重台梅","f":"七言绝句","c":["只将单萼缀层花，弱骨丰肌自一家。","戴几朵来谁可称，宝钗双燕绿云斜。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其四","f":"七言绝句","c":["初时华节漕江东，台阁争留省阁中。","换得一州如斗大，便无人挽信诗穷。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其三","f":"七言绝句","c":["闻道匆匆不住程，如今应已到乡城。","亦通朝路音书不，朝外可能空旧情。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其一","f":"七言绝句","c":["老子生来铁面皮，要渠嬉笑莫过诗。","可怜百巧卿云手，拙直今年一奏词。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其二","f":"七言绝句","c":["送公萧寺意徘徊，客众登车不忍归。","明日尚将诗寄我，要令鹤骨转难肥。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其五","f":"七言绝句","c":["少有羊曾踏菜园，更教清苦嚼筠根。","何如添得如椽笔，就向西江一口吞。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其六","f":"七言绝句","c":["螀寒蚓叫亦何心，老贼奚堪领活深。","非是交游无远别，几回因此惨离襟。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其七","f":"七言绝句","c":["诸子分镳不待鞭，愈怜肥犬满人前。","何须妙处趋庭说，心学乘閒尽底传。"]},{"t":"有怀新筠州杨秘监寄赠八绝兼桂隐茶 其八","f":"七言绝句","c":["茗芽封去且随书，林下多惭好物无。","鼻孔撩天犹得在，却须持赠竹香炉。"]},{"t":"杂兴 其三","f":"七言绝句","c":["细读南山扣角歌，机锋投处几曾多。","道人不踏门前路，敝帚其如自爱何。"]},{"t":"杂兴 其一","f":"七言绝句","c":["迢遥秦陇旧家山，百万貔貅拥节还。","读尽一编时自许，西风吹梦玉门关。"]},{"t":"次韵吕浩然四首 其四","f":"七言绝句","c":["天然风景异人为，门外南湖不姓西。","指日芙蓉盛行发，何须出郭看苏堤。"]},{"t":"次韵吕浩然四首 其三","f":"七言绝句","c":["秋水清来不钓鱼，有时遮眼强寻书。","过从闲客犹全少，况是朝官更合疏。"]},{"t":"次韵吕浩然四首 其二","f":"七言绝句","c":["作诗谁道有梯阶，当下由人肯放开。","字字不为声病缚，知君得处自天来。"]},{"t":"次韵吕浩然四首 其一","f":"七言绝句","c":["小筑茅堂亦有厅，规摹林野自然清。","仙风道骨真人后，过我应除喝道声。"]},{"t":"次韵京口叔祖见寄四首 其四","f":"七言绝句","c":["汲古无初不读书，屠苏新制帖僧庐。","痴禅昼夜蒲团上，贪睡犹胜学宰予。"]},{"t":"次韵京口叔祖见寄四首 其三","f":"七言绝句","c":["病起逢春自献酬，醉狂诗体类俳优。","追攀雄杰诚堪笑，寄去稽迟更合羞。"]},{"t":"次韵京口叔祖见寄四首 其二","f":"七言绝句","c":["山堂初展称婆娑，曲径移栽杂树多。","应是我翁归舍后，便登繁要亦来过。"]},{"t":"次韵京口叔祖见寄四首 其一","f":"七言绝句","c":["欲诉中心话许长，尺书恨不寄千张。","新篇喜逐东风好，变尽人间草木荒。"]},{"t":"次韵茂洪觅腊梅","f":"词","c":["世路?崟费折枝，退耕非我更其谁。","真花似假无心咏，只诵涪翁旧日诗。"]},{"t":"次韵姜邦桀见访留赠三诗 其二","f":"七言绝句","c":["绕林游遍更沿陂，薄暑车行不下帷。","最喜竹君相伴久，见渠生子子生儿。"]},{"t":"次韵姜邦桀见访留赠三诗 其一","f":"七言绝句","c":["饱看朝霞与暮云，一丘一壑大无尘。","关门果是倦迎客，倒屣还因有句人。"]},{"t":"次韵姜邦桀见访留赠三诗 其三","f":"七言绝句","c":["何曾一事扰中扃，醉便投床梦亦清。","书卷犹嫌旧时习，未能熟处放教生。"]},{"t":"次韵徐衡仲饷淮白鱼","f":"词","c":["谩浪功名付直钩，谁能鏖战学焚舟。","随人不但羹鱼美，解道江?似鹿头。"]},{"t":"次韵酬王之孟见赠","f":"七言绝句","c":["相逢未问有诗新，识得全然少得人。","莫怪世间多不爱，翰林憔悴少陵贫。"]},{"t":"次韵酬王梦得西湖上见寄","f":"七言绝句","c":["一萼香红未破尘，绿波惊眼自摇春。","晴新策蹇湖边去，供作他年画里人。"]},{"t":"次韵酬张郎中赋水蕉四首 其四","f":"七言绝句","c":["往年植处倚苍岏，曾蔽秋苔两席宽。","别后不因贪水宿，儿孙那得许萧寒。"]},{"t":"次韵酬张郎中赋水蕉四首 其三","f":"七言绝句","c":["诗卷寻常要往回，今朝却怕此诗来。","只缘快读清凉语，返觉林居有世埃。"]},{"t":"次韵酬张郎中赋水蕉四首 其二","f":"七言绝句","c":["火云空际正巑岏，漫瞰平湖百亩宽。","叶叶是风根是雪，一窗因尔忽生寒。"]},{"t":"次韵酬张郎中赋水蕉四首 其一","f":"七言绝句","c":["春去论年卒未回，溪头传信却先来。","绿笺展尽全无字，此语何堪谕俗埃。"]},{"t":"池上 其三","f":"七言绝句","c":["海榴如火发高丛，空斗炎炎烈日红。","争似栀花浑是雪，净香薰透一池风。"]},{"t":"池上 其二","f":"七言绝句","c":["波纹回处恰双鱼，小草花红点绿蒲。","不是幽人相管领，枉教造化着工夫。"]},{"t":"池上 其一","f":"七言绝句","c":["绿卷晴荷插满池，珍禽来惯帖船飞。","看云只似寻常立，何独今朝忘却归。"]},{"t":"池上木芙蓉欲开述兴二首 其二","f":"七言绝句","c":["岸巾三酌便酣眠，堕地鸾笺写未全。","明日满城人定说，若无诗累是神仙。"]},{"t":"池上木芙蓉欲开述兴二首 其一","f":"七言绝句","c":["芙蓉环望压波明，燕尾舟从绿处撑。","待得花成红沓堕，老夫天地锦纵横。"]},{"t":"池边二绝 其一","f":"七言绝句","c":["屡欲池边看晓烟，晓烟多是独贪眠。","红渠似怪人来晚，不肯回头却粲然。"]},{"t":"红佛见笑花","f":"七言绝句","c":["芳菲成梦雨廉纤，慰眼娇红敢浪嫌。","不但瞿昙当发笑，老夫初看亦掀髯。"]},{"t":"约斋","f":"五言绝句","c":["博学非能事，详言道转乖。","只因省气力，处处是吾斋。"]},{"t":"自锡山归舟中三首 其三","f":"七言绝句","c":["帆腰风便得归程，天末层云暗又明。","浅色鸡儿深色草，知谁教汝唤诗成。"]},{"t":"自锡山归舟中三首 其二","f":"七言绝句","c":["破驿遥临放马场，两鸦飞下更苍凉。","东风莫起雕鞍兴，白发欺人念故乡。"]},{"t":"自锡山归舟中三首 其一","f":"七言绝句","c":["墙上夭桃竹顶齐，矮桥横水屋横陂。","主翁受用三竿日，门外催租总不知。"]},{"t":"舟行观新月","f":"七言绝句","c":["一痕如掐夕天涯，望转青林出没时。","不是山高爱藏月，月光犹嫩怯人窥。"]},{"t":"舟过良渚","f":"七言绝句","c":["船出修门未有诗，直须凤口汎晴溪。","缘何触景方吟得，拙句频年不立题。"]},{"t":"芍药花二首 其二","f":"七言绝句","c":["吟笺欠向此花题，未信翻阶句绝奇。","三嗅苍髯惹黄粉，又成空对剪来枝。"]},{"t":"芍药花二首 其一","f":"七言绝句","c":["自古风流芍药花，花娇袍紫叶翻鸦。","诗成举向东风道，不愿旁人定等差。"]},{"t":"行次下渚湖二首 其二","f":"七言绝句","c":["野童绿草牧鹅群，诗料今朝得几分。","俯仰纵横皆合律，云如层树树如云。"]},{"t":"行次下渚湖二首 其一","f":"七言绝句","c":["绵延苍岫补林空，菱荇通船万镜中。","黄白花明如绣出，蜻蜓犹爱蓼成丛。"]},{"t":"行次德清 其三","f":"七言绝句","c":["渐凉山水倍清华，不说渔樵亦自嘉。","好是趁人全省力，龟溪才过又荷花。"]},{"t":"行次德清 其二","f":"七言绝句","c":["浮图立处觉天低，迎我船行十里时。","不是前山明复暗，那知头上白云移。"]},{"t":"行次德清 其一","f":"七言绝句","c":["波鸣船板唤晨兴，倦睫揩摩得梦醒。","到县阴晴休更问，野禽声已喜人听。"]},{"t":"西庄夜归","f":"七言绝句","c":["草声真似过田间，唧唧虫催兴未阑。","珍重小舆能从我，夜深穿遍竹阴寒。"]},{"t":"观水上斜照","f":"七言绝句","c":["吹落天河入水中，分明金镀晚来风。","若非日脚流成汁，平楚青还染得红。"]},{"t":"访安福寺叶上人","f":"七言绝句","c":["苍苔径入旧栽竹，树里桥横新凿池。","丈室稳居清绝地，岂容支遁不能诗。"]},{"t":"过枫桥寺","f":"七言绝句","c":["妙绝吾宗有旧题，趁晴径过敢留诗。","只消记取今朝景，不是乌啼月落时。"]},{"t":"过野翁亭因登岝崿山憩崇寿院僧轩共成四绝句 其二","f":"七言绝句","c":["溪流逢旱息潺淙，野彴横趋乱石中。","莫恨铁冠人已去，我来权合号山翁。"]},{"t":"过野翁亭因登岝崿山憩崇寿院僧轩共成四绝句 其一","f":"七言绝句","c":["古县依山惬乍游，欲行因路始穷幽。","搀空石壁樛林合，更做行程急也留。"]},{"t":"过野翁亭因登岝崿山憩崇寿院僧轩共成四绝句 其四","f":"七言绝句","c":["岩隈萧寺得跻攀，数翠邀岚不复难。","已向城中专一壑，更须随处款青山。"]},{"t":"丽秋花","f":"七言绝句","c":["疏翠巧装丹凤尾，素绡轻纽玉虫须。","春花莫把秋丛薄，若比娇妍总合输。"]},{"t":"何氏书堂","f":"七言绝句","c":["谁云学宦不同源，人镜风流百世存。","想见当年临案牍，必无书限误成根。"]},{"t":"余以雪牡丹歌呈诚斋回柬云只得籍没是兵家不传之妙谓不和答也又尝以来日立夏问诚斋所谓风月库中当作何措置蒙绝句示报因次韵致谢并破前说云","f":"七言绝句","c":["春风欲去难留住，措置无如信野人。","但解有诗随手和，自然日日是青春。"]},{"t":"初闻湖南蛙声成三诗 其二","f":"七言绝句","c":["竞喜蒿蓬月到时，莫嫌喧噪没新奇。","凭谁试问波神看，定诵南湖近日诗。"]},{"t":"初闻湖南蛙声成三诗 其一","f":"七言绝句","c":["杏花杨柳傍清明，淡沲风光画不成。","春到此时须急赏，绕堤今夜有蛙声。"]},{"t":"初闻湖南蛙声成三诗 其三","f":"七言绝句","c":["皇恩汪濊及虫鱼，尔得安心大泽居。","科斗未生休纵乐，吴侬倾听且防渠。"]},{"t":"即目","f":"七言绝句","c":["偶然看树过平桥，老尽墙边杞术苗。","不分蛛丝与蜗壳，也随残照集芳条。"]},{"t":"即事 其三","f":"七言绝句","c":["竹院桥廊未放晴，一凉生处绿交横。","隔林休厌荷池小，风叶时传泼雨声。"]},{"t":"即事 其二","f":"七言绝句","c":["旋买花栽得野香，浴兰天气日偏长。","槐龙或跃无人见，净扫风尘置竹床。"]},{"t":"即事 其一","f":"七言绝句","c":["池通幽涧碧如油，试水新鹅小拍浮。","行过板桥花片落，被风邀上采菱舟。"]},{"t":"吟诗","f":"七言绝句","c":["一日吟成九首诗，旁人都爱少瑕疵。","直须作到无人爱，始是我诗长进时。"]},{"t":"听莺亭","f":"七言绝句","c":["墙头正对南湖柳，湖柳迎风翠扫空。","最喜音声为佛事，乱蝉赓唱夕阳中。"]},{"t":"听琵琶","f":"七言绝句","c":["四弦么凤杂雏莺，不作商船塞路声。","花影透帘清昼夜，细将拢撚说多情。"]},{"t":"园中口占二首 其二","f":"七言绝句","c":["石楠花似碎琼花，只就香中便点茶。","欲识此堂奇绝处，山林朝暮不离家。"]},{"t":"园中口占二首 其一","f":"七言绝句","c":["荇带荷钱渐满池，吹香隔岸尽荼蘼。","潜鱼忽掷金梭起，补足今朝未了诗。"]},{"t":"园中杂书四首 其二","f":"七言绝句","c":["大田非但仰梅霖，百亩园中受赐深。","著子榴梢珠迸火，放花栀树玉抽金。"]},{"t":"园中杂书四首 其四","f":"七言绝句","c":["初生科斗聚如拳，鼓吹骎骎聒夜眠。","料得鱼蛮生妄想，曲车那解口流涎。"]},{"t":"园中杂书四首 其一","f":"七言绝句","c":["春云天上白成行，春草人间绿自香。","罨岸桃花三百树，碧溪休问短和长。"]},{"t":"园中杂书四首 其一","f":"七言绝句","c":["因病经旬不赋诗，无诗病思转难支。","今朝诗句未成了，已觉全无病可医。"]},{"t":"园中杂书四首 其四","f":"七言绝句","c":["黄昏桥上据胡床，青霭濛笼总是香。","未说居閒南面乐，且乘北面十分凉。"]},{"t":"园中雪夜二首 其二","f":"七言绝句","c":["急傍栏干唤酒杯，却嫌红烛炫高台。","新图水墨兼凝粉，展向冰溪镜面开。"]},{"t":"园中雪夜二首 其一","f":"七言绝句","c":["箫鼓喧阗乐夜堂，宝灯初试杂花光。","欲知富贵天然处，尽把园林脑子装。"]},{"t":"园步杂兴 其二","f":"七言绝句","c":["豆篱黄叶被蔬田，静极情怀似黯然。","居舍又从东壁看，柳梢浓处起厨烟。"]},{"t":"园步杂兴 其四","f":"七言绝句","c":["池心谁放叶舟横，莲蘤还如入夏生。","病起一天云意好，浅坡閒让鹿先行。"]},{"t":"园步杂兴 其三","f":"七言绝句","c":["无风寒色自凄迷，晚日低笼一径微。","竹里鸠藏初未觉，小车行过忽横飞。"]},{"t":"园步杂兴 其一","f":"七言绝句","c":["欢意千年孰与齐，恰如稚子候门时。","八旬半载争多少，匹似渊明已较迟。"]},{"t":"园步杂兴 其五","f":"七言绝句","c":["园中荒秽渐平治，老子何妨鬓有丝。","从此五行无晦气，一閒成就万篇诗。"]},{"t":"围绣亭","f":"七言绝句","c":["盘屈回廊面面同，顶门开窍更神通。","非关意匠玲珑巧，示现圆融转物功。"]},{"t":"张以道归自甬东先饷土物两诗为谢 其一","f":"七言绝句","c":["梨柿鱼盐来海上，殷勤持送与閒官。","缘何似得千金赠，明日重亲语笑欢。"]},{"t":"张以道归自甬东先饷土物两诗为谢 其二","f":"七言绝句","c":["红满芙蓉菊满黄，连朝衰病负秋光。","乘除自此无忧恼，醉赏家园一万场。"]},{"t":"张似之送栗子木瓜","f":"七言绝句","c":["带日零风色未乾，肯随槃俎斗斓斑。","客炉爆处从毡破，女手批时忌蜜悭。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其一","f":"七言绝句","c":["城里今年热异常，出城萧寺未全凉。","发毛吹尽人间暑，除是芙蕖十里香。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其九","f":"七言绝句","c":["高峰南北两浮图，桂隐相看四载馀。","休怪出关犹从我，有诗处处是侬居。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其六","f":"七言绝句","c":["白发催愁酒量悭，软尘盈袂饮尤难。","小童正对茶铛立，堪伴先生入画看。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其七","f":"七言绝句","c":["一色琉璃碧簟横，更无觞豆引飞蝇。","从渠日气如汤烈，不碍盆中数尺冰。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其五","f":"七言绝句","c":["临津台殿似蓬莱，柳色荒凉锁翠苔。","萍港不知人事改，通船如望帝尧来。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其三","f":"七言绝句","c":["松竹孤山处士居，高风落落有谁如。","南湖放鹤能迎客，景行先贤或未疏。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其八","f":"七言绝句","c":["撑傍羹鱼宋媪家，绿荷裹饭荐匏瓜。","玄真受用非随俗，尚欠风前雨笠斜。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其二","f":"七言绝句","c":["佳处湖山昔纵游，繁华常恨过清幽。","今朝莫入名园去，只向风蘋荡小舟。"]},{"t":"灵芝寺避暑因携茶具汎湖共成十绝 其四","f":"七言绝句","c":["西陵桥下最阴多，花外山明涌黛螺。","开遍酒楼人未上，几声烟断采菱歌。"]},{"t":"花仙馆","f":"七言绝句","c":["烟火心肠咏不真，风流娇贵却无尘。","何须更问花仙姓，便是扁舟共载人。"]},{"t":"苏堤观木芙蓉因见净慈明上人翌日惠诗酬赠二绝 其一","f":"七言绝句","c":["来访秋花本为诗，酒杯徵逐负幽期。","山中句出明书记，还了清邀一段奇。"]},{"t":"苏堤观木芙蓉因见净慈明上人翌日惠诗酬赠二绝 其二","f":"七言绝句","c":["口边白醭公家事，坐上清狂我辈真。","会乞一閒归故隐，定因能赋结高人。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其六","f":"词","c":["才晴便是看花时，夜雨何堪带雪吹。","春色更?过数日，三分馀一尚堪追。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其五","f":"七言绝句","c":["才晴便是看花时，休问花名是阿谁。","藉使无梅桃杏在，但能来赏莫嫌迟。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其四","f":"七言绝句","c":["才晴便是看花时，自看何如与客期。","亦有数篇花下句，苦无风味怕人知。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其三","f":"七言绝句","c":["才晴便是看花时，不觉飘香已满枝。","小道山翁如具眼，绿阴初试更相宜。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其二","f":"七言绝句","c":["才晴便是看花时，天上阴晴岂预知。","前日路乾居士病，偶妨招客酒樽随。"]},{"t":"走笔和曾无逸掌故约观玉照堂梅诗六首 其一","f":"七言绝句","c":["才晴便是看花时，记事君曾有四诗。","及至花开风日好，不闻拄杖扣疏篱。"]},{"t":"连朝","f":"七言绝句","c":["连朝溪雨溢荷塘，流水倾银万叶香。","不是风吹乱花侧，那知处处著鸳鸯。"]},{"t":"閒步游紫极观","f":"七言绝句","c":["孤榜前春冰雪清，山祠閒步意无营。","曾耽幽槩穿廊曲，犹记筠冠问客生。"]},{"t":"陆严州赴召喜成三诗 其二","f":"七言绝句","c":["荣辱心中总不疑，因公环召独成诗。","秪愁相见无多话，不似寻常梦里时。"]},{"t":"陆严州赴召喜成三诗 其三","f":"七言绝句","c":["知己从来自有天，除书宁复待人传。","青云直上非逾分，占上声名五十年。"]},{"t":"陆严州赴召喜成三诗 其一","f":"七言绝句","c":["精舍欣闻已解骖，风樯不易到江干。","一缄试读幽人语，莫作时情贺礼看。"]},{"t":"咏千叶缃梅 其二","f":"七言绝句","c":["忍冻拖筇月下看，烟笼繁影共汗漫。","缃裘不是多重数，争奈清宵尔许寒。"]},{"t":"咏千叶缃梅 其三","f":"七言绝句","c":["一枝深雪绽前村，冷落犹能役梦魂。","况有堆林春万叠，传餐甘此度朝昏。"]},{"t":"咏千叶缃梅 其一","f":"七言绝句","c":["巧留芳艳待春回，不受霜飙苦折摧。","应对群葩羞冷淡，数花并作一花开。"]},{"t":"咏千叶缃梅 其五","f":"七言绝句","c":["玉砌珠攒萼翠中，开时应是费东风。","临摹不著诗人手，剪綵徒劳蠹女工。"]},{"t":"咏千叶缃梅 其四","f":"七言绝句","c":["光摇层蕊望晴花，谁把鹅黄染练纱。","已是被香侵到骨，不须呼酒但烹茶。"]},{"t":"咏清苦","f":"七言绝句","c":["清苦任渠诗作祟，黑甜安尔睡为魔。","七言赋就赏音少，一枕觉来佳兴多。"]},{"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其一","f":"七言绝句","c":["挑尽灯花夜未眠，清寒浑忘是春天。","霜侵绿鬓张居士，空坐书帏三十年。"]},{"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其五","f":"七言绝句","c":["苕霅从来著志和，子云宁久占烟波。","速归径上清班好，时过南湖伴浩歌。"]},{"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其二","f":"七言绝句","c":["案上因翻简铁堆，亲朋何日和诗回。","高怀剩得清閒力，满纸溪山秀色开。"]},{"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其三","f":"七言绝句","c":["往事追思重惨伤，相从常醉德勋堂。","每登屺岵数鸿雁，老泪风前必数行。"]},{"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其四","f":"七言绝句","c":["宦情侬自本来无，君亦琳宫暂逸居。","西华武夷俱绝胜，可教诗卷此时疏。"]},{"t":"夜闻渔歌","f":"七言绝句","c":["非竹非丝响裂空，高歌三唱出渔篷。","清溪激越犹如许，想见湘波欸乃中。"]},{"t":"夜赋","f":"七言绝句","c":["月黑林间亦自奇，莲花两朵白如衣。","初疑野鹭池中立，试拍栏干嚇不飞。"]},{"t":"孟尝君","f":"七言绝句","c":["狗盗鸡鸣却遇知，可怜真士不逢时。","诗书若作空言看，凤至鸾游孰致之。"]},{"t":"绍兴间国工胡伟琵琶擅称一时其徒豪兴得胡心传之妙今年七十二清健伎益精从容话故都事使人感叹因书小诗与之","f":"七言绝句","c":["半生繁会想梨园，醒耳秋风凤语弦。","我亦秦关归未暇，故都休说汴河边。"]},{"t":"觅句","f":"七言绝句","c":["觅句先须莫苦心，从来瓦注胜如金。","见成若不拈来使，箭已离弦作么寻。"]},{"t":"金凤花","f":"七言绝句","c":["彩凤连翩小作群，萧条门巷独留春。","莫因繁冶生轻鄙，岁岁花开见主人。"]},{"t":"雨中闻雁","f":"七言绝句","c":["小雨终朝湿翠霏，渚蒲汀树白瀰瀰。","若嫌鸣雁无厌足，回到潮州又索诗。"]},{"t":"前后植木犀楼上有月台尽见诸山","f":"五言绝句","c":["盛世适亲逢，楼台得地雄。","无形兼有象，俱在太和中。"]},{"t":"南湖上观萍","f":"七言绝句","c":["风掠浮萍水面来，翠绡成段接还开。","无情却似多情物，不到诗中不肯回。"]},{"t":"南湖书事五首 其五","f":"七言绝句","c":["恍看滟滟紫金幢，日脚横澜万褶光。","吹到槛边争荡激，直疑身似水仙王。"]},{"t":"南湖书事五首 其四","f":"七言绝句","c":["水鸟鸿俦已可听，湱然分练蹙波声。","成群争似沙鸥少，别有高閒物外情。"]},{"t":"南湖书事五首 其三","f":"七言绝句","c":["科树梯斜倚暮晖，犬声如蛤透疏篱。","谢天排出江村景，副我凭栏一望时。"]},{"t":"南湖书事五首 其二","f":"七言绝句","c":["过午人家起灶烟，被风轻引向晴川。","须臾却与云阴杂，不碍玻璃镜自圆。"]},{"t":"南湖书事五首 其一","f":"七言绝句","c":["初来作舍少人行，桥外如今满市声。","绕岸种成桃间柳，一家和气万家生。"]},{"t":"南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其二","f":"七言绝句","c":["旋开斜港放船出，更著小亭临水看。","软红尘里江山景，便著丹青画亦难。"]},{"t":"南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其四","f":"七言绝句","c":["朝阳鸣凤国之祥，瑞事吾家鸥鹭行。","最爱几声烟外响，和他渔艇独敲榔。"]},{"t":"南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其一","f":"七言绝句","c":["居士园门甚处开，傍城犹未著楼台。","门前湖水三千尺，引得沙鸥亦肯来。"]},{"t":"南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其三","f":"七言绝句","c":["东家西家翁媪说，白洋湖自有多年。","何曾识见江鸥至，消得主人诗兴颠。"]},{"t":"南湖赋冬青花四首 其四","f":"七言绝句","c":["桂子休誇碧满园，小蒲萄实待霜繁。","他年隐处寻西宅，先认冬青拥寺门。"]},{"t":"南湖赋冬青花四首 其三","f":"七言绝句","c":["酷烈深怜格外香，树边苔气与苍凉。","莫教糁径浑如雪，快向青阴置竹床。"]},{"t":"南湖赋冬青花四首 其二","f":"七言绝句","c":["上林名字万年枝，高映宫墙侧映池。","不是移根閒地种，岁寒情性有谁知。"]},{"t":"南湖赋冬青花四首 其一","f":"七言绝句","c":["杂树花香少似君，雨馀风晓或斜曛。","行人不著清新句，亦合移时驻屐闻。"]},{"t":"春云","f":"七言绝句","c":["松边寒彩过前山，松下铺毡坐不还。","泽物为霖休自苦，且来相伴约斋閒。"]},{"t":"春日","f":"七言绝句","c":["银叶煎香细雨声，竹阴行处药花明。","麦光小楷临唐帖，更有人间第一清。"]},{"t":"春日汎舟南湖因遍游近港坐间书客所携四扇 其二","f":"七言绝句","c":["丝簧同上木兰船，细草熏熏柳色天。","要是有诗方称此，不然枉作地行仙。"]},{"t":"春日汎舟南湖因遍游近港坐间书客所携四扇 其一","f":"七言绝句","c":["远近高低锦树明，直疑春教蝶多情。","人间万事思量尽，只好园居过此生。"]},{"t":"春日汎舟南湖因遍游近港坐间书客所携四扇 其四","f":"七言绝句","c":["赏玩归来日未斜，门前春水绿杨遮。","园亭西畔晴尤好，一色墙头见杏花。"]},{"t":"春日汎舟南湖因遍游近港坐间书客所携四扇 其三","f":"七言绝句","c":["先须放棹绕湖游，倒看行云水底浮。","客去莫归朝市说，引渠无意作公侯。"]},{"t":"春风","f":"七言绝句","c":["春风日日过东墙，睡起人閒蝶自忙。","吹尽玫瑰能底惜，只缘销去一年香。"]},{"t":"春雪阻观梅花两诗嘲之 其一","f":"七言绝句","c":["弄珠萦佩白衣仙，游戏尘寰占岁前。","却被天公撒龙脑，拥教无地著云軿。"]},{"t":"春雪阻观梅花两诗嘲之 其二","f":"七言绝句","c":["雨声俄混雪声乾，泥泞林堂一到难。","藉使玉肌无冻粟，可能独自过春寒。"]},{"t":"残梅","f":"七言绝句","c":["雨丝吹冷透窗纱，忽忽东风管鬓华。","岂为梅残便无恨，草生时节胜看花。"]},{"t":"点视马驿因成两绝 其二","f":"七言绝句","c":["万里关山过险巇，风廊聊此憩权奇。","天开径上从兹始，想见长鸣振鬣时。"]},{"t":"点视马驿因成两绝 其一","f":"七言绝句","c":["别驾今晨检驿亭，道迎羸卒破铜钲。","当年错做书窗梦，蔽日旌旗出塞兵。"]},{"t":"珍林","f":"五言绝句","c":["李枣栗银杏，橙梨柿木瓜。","杨梅与金橘，不让满园花。"]},{"t":"盆橘","f":"七言绝句","c":["懒向江头置木奴，瓦盆聊玩绿垂珠。","何烦二老输赢决，始悟商山乐不殊。"]},{"t":"相士陈邦彦觅诗","f":"七言绝句","c":["眼力知君已绝伦，奉传一法更通神。","看渠天爵高人爵，方是人间富贵人。"]},{"t":"看雁","f":"七言绝句","c":["晓晴群雁欲何之，正是青天似纸时。","横斜数行有声字，服杀虚空解作诗。"]},{"t":"种腊梅喜成 其二","f":"七言绝句","c":["僧庐草剑石崖根，惯见西湖不喜论。","安得便如居士意，移为官舍读书轩。"]},{"t":"种腊梅喜成 其一","f":"七言绝句","c":["道旁方讶扑人香，金蓓花开满担装。","尚有松钗挂枝杪，买归偏称插山堂。"]},{"t":"荠花","f":"七言绝句","c":["荠花繁处蝶争飞，忽忆前年三月时。","流水流杯人共醉，晚来疏雨又新诗。"]},{"t":"药溪","f":"五言绝句","c":["野药随宜种，芎苗嚼最香。","屐痕休厌数，桤树逐溪长。"]},{"t":"送马舍人赴建康军幕","f":"七言绝句","c":["柳营谋客自枫宸，去去尖风雁字匀。","莫把吟诗替横槊，新亭北望正愁人。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其六","f":"七言绝句","c":["老僧分袂倏三年，犹记芳池跃翠泉。","新叠两山都未识，北堂引看更东偏。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其五","f":"七言绝句","c":["南山好处刘家寺，门里松篁一径冲。","自有禽声喜迎客，不须知事更鸣钟。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其四","f":"七言绝句","c":["岭度慈云境累凉，前看湖面后看江。","诗魔半饷难调伏，除是休来却易降。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其三","f":"七言绝句","c":["山腰路转涌苍蛇，山下修筠媚白沙。","正要澄江舒倦眼，莫教缘岸有人家。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其二","f":"七言绝句","c":["野香别是一般风，蓦直平冈好翠松。","更许虚空画山水，细铺霞浪衬云峰。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其一","f":"七言绝句","c":["故殿檐阴石汇泉，针鱼苔净乐回旋。","持杯挹取虽无暇，照影心肠更洒然。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其十","f":"七言绝句","c":["欲归停驭重徘徊，破费林间雪一杯。","留取半山看未了，火云时节约重来。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其九","f":"七言绝句","c":["亭桥两面看芙蕖，静数波间小队鱼。","碧幛弯环遮去路，净天终待此同居。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其八","f":"七言绝句","c":["井分泉脉透巉岩，谁道飞流是假山。","水鸟树林皆作供，可怜居士只偷閒。"]},{"t":"送客至无相兰若归过慈云岭小憩崇寿寺书所见十首 其七","f":"七言绝句","c":["支径坡陀竹最多，箨龙才起更成窠。","穿岚触翠坳塘出，一片香来得嫩荷。"]},{"t":"送酒诚斋将以五字","f":"五言律诗","c":["不应杨秘监，无暇问南湖。","桂树又花发，莲池和叶枯。","雨声秋最好，尊酒客非无。","寄去撩诗眼，深惭句法粗。"]},{"t":"送樱桃与范尚书二首 其二","f":"七言绝句","c":["满架酴醾雪未乾，滴阶红颗照春残。","知公有意参金鼎，驰送朝霞九转丹。"]},{"t":"送樱桃与范尚书二首 其一","f":"七言绝句","c":["谁将绛蜡千枝泪，镕作骊龙百斛珠。","酪盌冰盘非我称，敢烦西子荐陶朱。"]},{"t":"香玉花","f":"五言绝句","c":["髣髴是荼蘼，金沙著白衣。","香于佛见笑，大似野蔷薇。"]},{"t":"鸥渚亭次韵茂洪西湖三诗 其一","f":"七言绝句","c":["出城犹记四年前，朝看西湖到暮烟。","自有南湖相暖热，可曾频过六桥边。"]},{"t":"鸥渚亭次韵茂洪西湖三诗 其三","f":"七言绝句","c":["尘土奔忙举世人，无过白白鬓毛新。","一般要撰眼前乐，泉石由来乐较真。"]},{"t":"鸥渚偶成二首 其二","f":"七言绝句","c":["去去西南绿筱湾，折旋遵渚又飞还。","轻拳击水纤鳞起，滴沥波明一带间。"]},{"t":"鸥渚偶成二首 其一","f":"七言绝句","c":["昼阴无意到湖亭，引客悠然试一行。","便有同盟数公在，冒烟挥袂喜相迎。"]},{"t":"夏日南湖汎舟因过琼华园六首 其六","f":"七言绝句","c":["滑泥宁复问怀沙，且醉杯中琥珀霞。","触事背时还独笑，安排明日取虾蟆。"]},{"t":"夏日南湖汎舟因过琼华园六首 其五","f":"七言绝句","c":["诗思浑如菖歜苦，宦名那似术羹香。","朝来但听霏微雨，自种丛榴怪石傍。"]},{"t":"夏日南湖汎舟因过琼华园六首 其四","f":"七言绝句","c":["头上云忙雨欲来，箬篷还转碧芦隈。","中流数点沾衣湿，便放西山夕照开。"]},{"t":"夏日南湖汎舟因过琼华园六首 其二","f":"七言绝句","c":["草生荒径没靴深，寂寂危亭藓晕侵。","翠辇不来知几夏，野禽啼暝古松林。"]},{"t":"夏日南湖汎舟因过琼华园六首 其一","f":"七言绝句","c":["淡日轻阴晒麦天，水边閒唤木兰船。","不游东港西陂熟，争得人知是散仙。"]},{"t":"夏日南湖汎舟因过琼华园六首 其三","f":"七言绝句","c":["两岸人家水映门，谁知城里有深村。","照畦罂粟红灯密，绕舍戎葵紫缬繁。"]},{"t":"夏夜二首 其二","f":"七言绝句","c":["天上星辰金玉棋，输赢何日是分时。","多应却笑张居士，绮语妄言无了期。"]},{"t":"夏夜二首 其一","f":"七言绝句","c":["灯晕纱笼静者居，夜凉携扇绕阶除。","松间有句松间说，不向空中咄咄书。"]},{"t":"晓边","f":"七言绝句","c":["晓边花面雨濛松，莺避金丸翠竹丛。","春半风光自招举，按歌姑洗旋移宫。"]},{"t":"桂隐纪咏四十八首 其二十七 云外亭","f":"五言绝句","c":["芒屦方疑湿，天晴径又乾。","由来云在下，木杪是栏干。"]},{"t":"桂隐纪咏四十八首 其四十二 心足寮","f":"五言绝句","c":["闻道华胥国，依稀似醉乡。","近来参得透，睡稳不因床。"]},{"t":"桂隐纪咏四十八首 其二 东寺","f":"五言绝句","c":["数举营巢债，才成作佛庐。","随堂展单钵，均是道人居。"]},{"t":"桂隐纪咏四十八首 其三十八 平桥","f":"五言绝句","c":["桥向平边度，风从阔处来。","泠然旬五日，无去亦无回。"]},{"t":"桂隐纪咏四十八首 其四十 归喜桥","f":"五言绝句","c":["半岁吏尘役，天书教放归。","思量难报称，安稳饭和衣。"]},{"t":"桂隐纪咏四十八首 其十二 传经轩","f":"五言绝句","c":["香炷对清晨，微言得问津。","所师非传癖，手泽仰如新。"]},{"t":"桂隐纪咏四十八首 其六 安閒堂","f":"五言绝句","c":["不作风波民，已铸赫胥印。","同好岂无人，望崖行少进。"]},{"t":"桂隐纪咏四十八首 其三十四 听莺亭","f":"五言绝句","c":["不向他园去，能来共竹林。","故乡知我念，特地奏秦音。"]},{"t":"桂隐纪咏四十八首 其二十八 沙际亭","f":"五言绝句","c":["小楫轻撶去，无人伴此翁。","午烟青一点，鱼虎出深丛。"]},{"t":"桂隐纪咏四十八首 其二十六 依绿亭","f":"五言绝句","c":["月出烟暝时，水调谁家唱。","短棹欲相寻，先经此亭上。"]},{"t":"桂隐纪咏四十八首 其二十三 拥山亭","f":"五言绝句","c":["掩抱复回环，亭居紫翠间。","思量天下物，谁更好如山。"]},{"t":"桂隐纪咏四十八首 其十六 易容轩","f":"五言绝句","c":["世界无非我，心怀即是天。","玉堂并草舍，何地不安然。"]},{"t":"桂隐纪咏四十八首 其三十五 松桥","f":"五言绝句","c":["欲向松间去，梅西竹坞穿。","莫言吟兴在，风雪灞桥边。"]},{"t":"桂隐纪咏四十八首 其十八 玩芝轩","f":"五言绝句","c":["阴洞亲寻遍，灯惊蝙蝠飞。","坚明敲紫玉，一似采时肥。"]},{"t":"桂隐纪咏四十八首 其三十七 柳桥","f":"五言绝句","c":["初因桥种柳，却用柳名桥。","桂隐从兹入，春风莫浪招。"]},{"t":"桂隐纪咏四十八首 其二十 俯巢轩","f":"五言绝句","c":["化国舒长日，林隈分外知。","年年庭荫匝，数遍鹊寻儿。"]},{"t":"桂隐纪咏四十八首 其二十五 俯镜亭","f":"五言绝句","c":["唤作大圆镜，波文从此生。","何妨云影杂，榜样自天成。"]},{"t":"桂隐纪咏四十八首 其十一 殊胜轩","f":"五言绝句","c":["杜老诗中佛，能言竹有香。","欲知殊胜处，说著早清凉。"]},{"t":"桂隐纪咏四十八首 其十七 泰定轩","f":"五言绝句","c":["触处天光发，何尝离定中。","问云谁散乱，又道主人公。"]},{"t":"桂隐纪咏四十八首 其十五 真如轩","f":"五言绝句","c":["翠竹是真如，目前须荐取。","恁么做禅和，被人鞔似鼓。"]},{"t":"桂隐纪咏四十八首 其十三 读易轩","f":"五言绝句","c":["大易缘何有，难逃此问中。","不从横画会，爻象总能通。"]},{"t":"桂隐纪咏四十八首 其五 高寒堂","f":"五言绝句","c":["下瞰东邻寺，钟声殷两山。","贪吟尝忍冷，薄夜不知还。"]},{"t":"桂隐纪咏四十八首 其八 清夏堂","f":"五言绝句","c":["夜月三杯色，晴荷十亩香。","若教兴世念，不甚觉风凉。"]},{"t":"桂隐纪咏四十八首 其三十一 琼莩亭","f":"五言绝句","c":["莫羡海棠色，听言著子时。","骊珠千万颗，撒向嫩桑枝。"]},{"t":"桂隐纪咏四十八首 其三十三 满霜亭","f":"五言绝句","c":["疑驾洞庭帆，累累看绕山。","花时芳气洁，伯仲素馨间。"]},{"t":"桂隐纪咏四十八首 其十 煨芋轩","f":"五言绝句","c":["煖坐无寒涕，窗油雪让明。","地炉糠火熟，饱听乱松声。"]},{"t":"桂隐纪咏四十八首 其三十二 粲金亭","f":"五言绝句","c":["柘弹黄金子，谁将满树装。","珍禽来往惯，风落不惊忙。"]},{"t":"桂隐纪咏四十八首 其二十九 鲈乡亭","f":"五言绝句","c":["溪叟挈笭箵，曾来候此亭。","未知余不杀，刚要著鱼经。"]},{"t":"桂隐纪咏四十八首 其三十 摘霞亭","f":"五言绝句","c":["一片吹来锦，人言是杏花。","倚栏堪把玩，胜似日边霞。"]},{"t":"桂隐纪咏四十八首 其七 翠樾堂","f":"五言绝句","c":["宝画光腾处，乔林更碧峦。","权衡主人福，压尽世间官。"]},{"t":"桂隐纪咏四十八首 其四十一 静乐庐","f":"五言绝句","c":["城市非无地，如何此结庐。","一家耽静乐，两个水边居。"]},{"t":"桂隐纪咏四十八首 其四十六 樵径","f":"五言绝句","c":["路入前山处，苍苔裹石棱。","不逢负薪叟，时见隔林僧。"]},{"t":"桂隐纪咏四十八首 其四十八 舣蘋舟","f":"五言绝句","c":["玉立蜻蜓小，香欺漫港秋。","百年清绝意，孤棹抵封侯。"]},{"t":"桂隐纪咏四十八首 其四十七 霞川","f":"五言绝句","c":["方舟卧看花，丹霞二三里。","穷眼谢玄晖，休言馀散绮。"]},{"t":"桥亭观月","f":"七言绝句","c":["全似苍崖涌月轮，暗林横贯一溪明。","家中幻出山中景，圯上追凉恰二更。"]},{"t":"桥廊上作 其二","f":"七言绝句","c":["千载清风笠泽仙，提携曾置笔床边。","吾行不汲长桥水，要煮青山陆羽泉。"]},{"t":"涧西閒汎","f":"五言绝句","c":["曲曲通航小，兰桡手自移。","映丛怜白鹭，特地过湾迟。"]},{"t":"读韩非传","f":"七言绝句","c":["谏鼓招言事蔑闻，昧时自鬻更纷纷。","胸中著许堤防策，不救危身肯济君。"]},{"t":"铁行者","f":"七言绝句","c":["僧舍生涯只且然，养他行者不须钱。","龙潭莫问僧参得，吹灭灯时各自眠。"]},{"t":"堂中安奉高宗寿皇今上御书碑","f":"七言绝句","c":["路转修林特地殊，九光霞气羃仙庐。","苍瑶不刻飞天篆，尽是三清玉帝书。"]},{"t":"宿上湖","f":"七言绝句","c":["落日烘蒙紫翠间，舟人遥指洞庭山。","云情水态明朝看，且伴新蟾宿柳湾。"]},{"t":"崇德道中 其二","f":"七言绝句","c":["羊蹄根老漫溪浔，灰蝶閒飞兴亦深。","春色醉人胜似酒，觅诗天气要微阴。"]},{"t":"崇德道中 其三","f":"七言绝句","c":["疏篱遮竹竹难遮，卧向溪流一桁斜。","绿底睡凫应自爱，起来摇翅各成花。"]},{"t":"崇德道中 其四","f":"七言绝句","c":["枸橘花繁雪有香，风吹成阵入船舱。","若教知我园中路，不肯芳菲驿舍傍。"]},{"t":"崇德道中 其一","f":"七言绝句","c":["破艇争划忽罢喧，野童村女闯篱边。","令人说著苏堤路，花满清明画鼓船。"]},{"t":"得巨鱼送叔祖","f":"七言绝句","c":["桃花流水正关渠，雨后俄收紫鲙鱼。","岂是斋厨真欠此，小诗聊当腹中书。"]},{"t":"得巨笋三尺围送王叔兴","f":"七言绝句","c":["猫头名字出长沙，别号犀株岂过誇。","好对竹尊招二子，藕如船大枣如瓜。"]},{"t":"得家书 其一","f":"七言绝句","c":["北堂萱独雁行疏，旅梦通宵只敝庐。","未暇拆封忙唤仆，先将安否问何如。"]},{"t":"得家书 其二","f":"七言绝句","c":["玉塞金河阻去程，醉中尝梦赋西征。","天时不与人心合，独守寒窗数雁声。"]},{"t":"得家书 其三","f":"七言绝句","c":["风沙来往稻粱谋，江北江南一岁遒。","非为红楼断消息，待梅暗候自清愁。"]},{"t":"晚兴","f":"五言绝句","c":["江汉旧名侯，飘萧发未秋。","时荣那似此，天地入诗游。"]},{"t":"晚步松下","f":"七言绝句","c":["人皆束缚夘申时，我独园居不必归。","最是苍寒堂下好，乱松稍上看云飞。"]},{"t":"晚眺","f":"七言绝句","c":["小阁梯檐竹作篱，晴阴登眺百盘宜。","悬知皓月升云海，不赋如钩似镜诗。"]},{"t":"晨步西涧","f":"七言绝句","c":["日炙芹泥积渐融，一湾新涨小桥通。","不因野鸭飞来喜，忘却生涯书卷中。"]},{"t":"曹村观落日","f":"七言绝句","c":["日欲西时暮霭凝，何尝落向远山层。","分明万丈青罗幕，遮却销金罩里灯。"]},{"t":"望亭夜泊","f":"七言绝句","c":["新月何曾展画帏，便教星斗避寒辉。","思量自在天公最，昨日峰头有雪飞。"]},{"t":"梅 其二","f":"词","c":["驱鹤松门去却回，似知草际有香来。","青条红眼才窥煖，拄杖先?费绿苔。"]},{"t":"梅 其一","f":"七言绝句","c":["群玉山头昨梦归，占祥获应必无疑。","今朝暂歇抄书课，急为寒梅办早诗。"]},{"t":"梅 其三","f":"七言绝句","c":["冒寒岗路透溪桥，驴仆翩翩叶乱飘。","还是去年初见处，青旗茅店恰相招。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其十","f":"七言绝句","c":["小臣奕世沐深恩，寓直蓬山三十春。","空抱一编无所用，也叨拜望属车尘。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其九","f":"七言绝句","c":["黎庶曾何帝力知，七旬三入乂宁时。","春寒谁怕妨花柳，一日东风万国吹。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其八","f":"七言绝句","c":["圣父移居太母傍，銮舆躬侍袭龙香。","乍从黄伞窥天表，愈觉英资似寿皇。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其七","f":"七言绝句","c":["和风淑气夹钟初，寿域重开际八区。","不战自令边徼服，喜看风动媲唐虞。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其六","f":"七言绝句","c":["聪哲从来简帝心，万方臣子合君临。","东堂议事犹经岁，仰体慈皇属意深。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其五","f":"七言绝句","c":["百僚重入贺新君，亿载从今仰大昕。","文德岂惟循舜道，武功行见访尧勋。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其四","f":"七言绝句","c":["宣召班排过隔廊，耸闻神器授储皇。","只将揖逊为家法，我宋真宜万代昌。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其三","f":"七言绝句","c":["深严黼座瑞光中，彷佛遥瞻穆穆容。","特衣赭袍缘底事，御天嗣圣欲乘龙。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其二","f":"七言绝句","c":["只似閒时朝殿来，华驹徐步转东街。","铜门已见飞腾象，先下浑银两字牌。"]},{"t":"淳熙巳酉二月二日皇帝登宝位镃获厕廷绅辄成驩喜口号十首 其一","f":"七言绝句","c":["晓色葱茏丽建章，今辰天地不寻常。","中宵若没阴云蔽，应见前星日样光。"]},{"t":"清明日书亦庵壁二首 其二","f":"七言绝句","c":["光阴高柳欲飘绵，拂著蔷薇锦壁连。","莫道行人总无识，定因罗爵爱门前。"]},{"t":"清明日书亦庵壁二首 其一","f":"七言绝句","c":["春情缘雨复缘晴，晴即閒行雨即吟。","花好满园看未遍，出墙邻树又关心。"]},{"t":"绿筠轩旧在于潜寂照寺今移立县治之东竹间凿小池植莲为赋两绝 其一","f":"七言绝句","c":["按图得此已欣然，胜趣何尝有变迁。","一把香茅千个玉，不妨邂逅揖苏仙。"]},{"t":"绿筠轩旧在于潜寂照寺今移立县治之东竹间凿小池植莲为赋两绝 其二","f":"七言绝句","c":["气韵非关竹有无，莫嫌清荫杂芙蕖。","官居不俗从何得，窗下风翻未尽书。"]},{"t":"谒陆礼部归偶成二绝句 其二","f":"七言绝句","c":["有口宁论黠与痴，相投无过只谈诗。","要知此客非忙客，欲去迟回尚读碑。"]},{"t":"谒陆礼部归偶成二绝句 其一","f":"七言绝句","c":["欲识清狂自在身，关门湖上独经春。","今朝正接黄梅雨，却出冲泥访故人。"]},{"t":"骑鲸桥","f":"七言绝句","c":["池港开门就作桥，朱栏相望压鲸腰。","风摇慢摺游溶绿，波底何妨著霁霄。"]},{"t":"寒食前一日西湖閒泛三首 其三","f":"七言绝句","c":["衰鬓争如竹际苔，秋千犹记玉骢回。","短篱数尺花成簇，一日春悰不往来。"]},{"t":"寒食前一日西湖閒泛三首 其二","f":"七言绝句","c":["骤暖悬知雨信浓，半阴台榭碧烘濛。","何心更敢携壶去，孤桨微吟尚未工。"]},{"t":"寒食前一日西湖閒泛三首 其一","f":"七言绝句","c":["艳红香白遍游人，花柳酣歌识太平。","野客独谙閒意趣，草烟空爱一川明。"]},{"t":"敬和东宫早梅二首 其二","f":"七言绝句","c":["乾坤连夜玉为尘，照映冰容面面新。","句妙莫疑难属和，真成白雪对阳春。"]},{"t":"敬和东宫早梅二首 其一","f":"七言绝句","c":["月质风裳不受尘，独从天上巧呈新。","情知压倒横斜语，青震专回万木春。"]},{"t":"暂归桂隐杂书四首 其四","f":"七言绝句","c":["茅屋烟升正早炊，覆墙高柳涨新枝。","飞绵莫便沾泥去，旧爱疏篱雪下时。"]},{"t":"暂归桂隐杂书四首 其三","f":"七言绝句","c":["诗料无穷满目前，只须拈出见成篇。","骑兵莫道随官俗，也解争奴曲涧船。"]},{"t":"暂归桂隐杂书四首 其二","f":"词","c":["作双鸂?住方池，乐此荷钱近钓矶。","应笑主翁尘袂黑，故从清泚浣红衣。"]},{"t":"暂归桂隐杂书四首 其一","f":"七言绝句","c":["风院帘垂飐翠旌，茂阴疏转表新晴。","清和自是常年景，有底今番触拨人。"]},{"t":"暂住新市行次谢村二首 其二","f":"七言绝句","c":["推窗面面得凉多，陂泺风翻渴水荷。","人语忽惊群鹜起，隔芦知是小船过。"]},{"t":"暂住新市行次谢村二首 其一","f":"七言绝句","c":["笼丛灌木绕低田，一雨催鸣尔许蝉。","平日诗怀何处吐，今年秋色此行先。"]},{"t":"暂往嘉兴离桂隐过渡","f":"七言绝句","c":["侧望山来起复平，横冲波去碧还明。","谁言身在笱舆上，自是乘风空里行。"]},{"t":"暑行","f":"七言绝句","c":["谁敲白石生热烟，举头见岭思回鞭。","修竹林间有寒甃，莫打渴乌教近前。"]},{"t":"曾幼度许过访两诗问讯 其一","f":"七言绝句","c":["寒窗不住阅清文，炼石真为五色云。","拄杖横担东鲁教，长安今次欲谁闻。"]},{"t":"曾幼度许过访两诗问讯 其二","f":"七言绝句","c":["诗不能工张约斋，有人曾说访渠来。","病馀百拙慵开口，愿听晴空起怒雷。"]},{"t":"湖南午坐雨作归山堂共成四绝句 其四","f":"七言绝句","c":["平时吾亦爱吾庐，今雨巢禽亦引雏。","好是阶前四高桧，枝枝叶叶缀明珠。"]},{"t":"湖南午坐雨作归山堂共成四绝句 其二","f":"七言绝句","c":["或拟香山或拟陶，有时无句只虫号。","作诗藞苴犹之可，字写不成方是高。"]},{"t":"湖南午坐雨作归山堂共成四绝句 其三","f":"七言绝句","c":["西山俄起一声雷，不觉如拳雨点来。","滴遍池中万荷叶，又催薝卜海榴开。"]},{"t":"湖南午坐雨作归山堂共成四绝句 其一","f":"七言绝句","c":["帘外青山隐树林，霎时来看便沉吟。","骑声盖色都除尽，唯恨诗情染最深。"]},{"t":"武子得监左帑归甬东待次","f":"七言绝句","c":["看湖初过月阴阴，同望灯廛话夜深。","帆向西兴人便远，再来华近莫相寻。"]},{"t":"登春陌","f":"五言绝句","c":["花柳燄通津，幽居日日春。","门前往来者，同是华封人。"]},{"t":"谢人送白山茶花二首 其二","f":"七言绝句","c":["屋角春声喜报晴，青裳玉面晓妆明。","为君自断天休问，依倚清香乐此生。"]},{"t":"谢人送白山茶花二首 其一","f":"七言绝句","c":["韵胜初闻不记年，偶逢俄在软红边。","山矾不遇南昌老，争得嘉名亚水仙。"]},{"t":"道傍丛祠榜云老人庙","f":"七言绝句","c":["里俗崇祠想报功，袍靴包裹雪髯翁。","休嗟事始无人识，纵有丰碑亦是空。"]},{"t":"集英殿立侍观进士唱名六首 其六","f":"七言绝句","c":["科目从来本自宽，才疏秪合作粗官。","雕虫半世将何用，可惜南湖负钓竿。"]},{"t":"集英殿立侍观进士唱名六首 其五","f":"七言绝句","c":["先世亲题雁塔名，宦途漂泊最关情。","难将此语逢人举，归问寒斋旧短檠。"]},{"t":"集英殿立侍观进士唱名六首 其四","f":"七言绝句","c":["青衫如草照春塘，争傍龙墀捧敕黄。","功业便从今日去，莫教人道只文章。"]},{"t":"集英殿立侍观进士唱名六首 其三","f":"七言绝句","c":["君王策士几临轩，好学隆儒古莫肩。","忠鲠尽将裨治道，不令鼌董誉空传。"]},{"t":"集英殿立侍观进士唱名六首 其二","f":"七言绝句","c":["山绕彤城瑞雾凝，催班晓色渐分明。","龙门肃立章身别，得著银袍却最荣。"]},{"t":"集英殿立侍观进士唱名六首 其一","f":"七言绝句","c":["早放天扉一刻开，更声初断雨声催。","不因变化鱼龙日，焉有风云转首来。"]},{"t":"携杨秘监诗一编登舟因成二绝 其一","f":"七言绝句","c":["今日何曾独自来，船中相伴有诚斋。","须知不局诗编里，妙用方能处处皆。"]},{"t":"携杨秘监诗一编登舟因成二绝 其二","f":"七言绝句","c":["造化精神无尽期，跳腾踔厉即时追。","目前言句知多少，罕有先生活法诗。"]},{"t":"新市道中","f":"七言绝句","c":["野晴天碧共溪长，画样飞来白鸟双。","舟小不禁风罨岸，菰蒲无数入篷窗。"]},{"t":"新诗 其二","f":"七言绝句","c":["一酌桥亭即便回，雪粘桃树学疏梅。","若教湖上鸥来了，此日真须三百杯。"]},{"t":"新诗 其一","f":"七言绝句","c":["飞雪年年似故人，相逢真味一番新。","别来莫问尘寰事，鬓色几如雪色匀。"]},{"t":"新种","f":"七言绝句","c":["新种枇杷花便稠，被香勾引过溪头。","黄蜂紫蝶都来了，先赏输渠第一筹。"]},{"t":"煎白云茶二首 其二","f":"七言绝句","c":["嫩芽初见绿蒙茸，已破人间睡思浓。","玉食会当陪上苑，贵名高冠密云笼。"]},{"t":"煎白云茶二首 其一","f":"七言绝句","c":["水西幽寺风光足，山上行云雪色明。","不放精英入閒草，夜铛嘉话得松声。"]},{"t":"简马庄父","f":"七言绝句","c":["才名曾道相君知，少忍黄粱数日炊。","堪笑南湖愈疏拙，相逢无话说多时。"]},{"t":"漫兴 其二","f":"七言绝句","c":["茆舍丝瓜弱蔓堆，漫陂鹎鸭去仍回。","开帘正恨诗情少，风捲野香迎面来。"]},{"t":"漫兴 其一","f":"七言绝句","c":["乐天閒适文章累，陶令归来儿子忧。","两事吾今浑放下，看山临水更何愁。"]},{"t":"腊梅二首 其二","f":"七言绝句","c":["家世凌风却月旁，别来衣变郁金光。","神仙定遇容成子，教服三黄遍体香。"]},{"t":"腊梅二首 其一","f":"七言绝句","c":["金谷园中夜罢炊，照花滴腊上林枝。","清芬更比寒梅耐，不是蜂房借蜜脾。"]},{"t":"嘲蝶","f":"七言绝句","c":["柳外飞飞蛱蝶儿，惠风心性彩云姿。","终朝守定墙头舞，不得邻家一句诗。"]},{"t":"潘茂洪借屋地主催起仆以山园暂假寓泊书两诗送之 其二","f":"七言绝句","c":["种艺吾方屋数间，图书鸡犬称君閒。","径携桃叶航湖去，别有新居却载还。"]},{"t":"潘茂洪借屋地主催起仆以山园暂假寓泊书两诗送之 其一","f":"七言绝句","c":["竹栽方讶不成阴，寸地城中果寸金。","莫使无家轻发叹，北山园里翠烟深。"]},{"t":"题山长庵","f":"七言绝句","c":["相国归来未肯閒，自将日月炼成丹。","思量漫把黄金铸，一段精神画亦难。"]},{"t":"题水墨画水仙木犀 其二","f":"五言绝句","c":["昔年风露乡，裙破郁金黄。","别来参祖意，坏色染衣裳。"]},{"t":"题水墨画水仙木犀 其一","f":"词","c":["翠袖擎金?，香风动宝车。","几间莫轻觑，故故薄云遮。"]},{"t":"题左顾亭","f":"七言绝句","c":["物我何曾有异同，莫言龟印偶相逢。","水中放去炉中得，心法须知一镜空。"]},{"t":"题平甫弟梁溪庄园","f":"五言绝句","c":["两字虽差远，花繁好作名。","假饶千万偈，难状尔多情。"]},{"t":"题本觉寺 其一","f":"七言绝句","c":["绕架蒲萄叶尚稀，瓦炉閒炷柏烟微。","年年绿暗轩窗意，却恨春风不早归。"]},{"t":"题本觉寺 其二","f":"七言绝句","c":["一径横穿藓翠封，满空声动玉琤淙。","林居岂是无修竹，未有清阴似此浓。"]},{"t":"题苍云亭","f":"七言绝句","c":["老桧分行直瓦亭，激泉岩罅骨毛醒。","从来庐阜太行眼，对此须教一样青。"]},{"t":"题画扇","f":"七言绝句","c":["谁将琢月挥云笔，偃仰江山尺素中。","眼界未舒君莫厌，出门三丈软尘红。"]},{"t":"题南山刘家寺松云轩","f":"七言绝句","c":["红蘤墙头蜂过叶，翠藤池面蚁行枝。","暂来数刻有馀兴，若住此轩何限诗。"]},{"t":"题挂剑图","f":"七言绝句","c":["当年许与有谁知，人忽邱陵我独悲。","逊国曩时犹易耳，不应留剑使心欺。"]},{"t":"题禹庙二首 其二","f":"七言绝句","c":["为人心切屡忘家，力量方知有等差。","莫信空山葬冠剑，且吟古屋画龙蛇。"]},{"t":"题禹庙二首 其一","f":"七言绝句","c":["从来大智特闲闲，手足胼胝意不艰。","千古夏王崇庙祀，浚川功用只随山。"]},{"t":"题赵祖文画","f":"七言绝句","c":["破烟飞鹭不排行，林外青山閟晓光。","村犬吠人循岸走，见成诗句省思量。"]},{"t":"题圆觉寺跳珠轩","f":"七言绝句","c":["箨龙来向石根蟠，幻出摩尼跃翠盘。","今日山中晴亦雨，可无风过发清寒。"]},{"t":"题扇","f":"七言绝句","c":["梧竹风来玉枕凉，月高偏爱占华堂。","休言境界亲曾有，画出如闻夜气香。"]},{"t":"题荷花画屏","f":"七言绝句","c":["芙蓉世界水为宫，宴处铿轰沸鼓钟。","后乘舞妃香十里，月寒谁见晓骑龙。"]},{"t":"题郭水坚画美人二首 其二","f":"七言绝句","c":["云亸钗梁倚鬓鸦，玉温冰洁谢铅华。","欲知占断人间韵，便是春风最后花。"]},{"t":"题郭水坚画美人二首 其一","f":"七言绝句","c":["从来憨态最难宜，只把红绡映雪肌。","自是一枝香杏了，莫嫌都不带花枝。"]},{"t":"题崔悫画白鹭伺龟","f":"七言绝句","c":["能言元绪已失计，潜来公子尤多机。","藏头壳里勿自暴，曳尾泥中胡不归。"]},{"t":"题瑞香花扇","f":"五言绝句","c":["梦里谁曾见，香篝紫绣蒙。","枝间两飞蝶，我共漆园翁。"]},{"t":"燕坐 其二","f":"七言绝句","c":["为君刻意五七字，甫壮知心一两人。","百计纵疏终办此，直疑贾孟是前身。"]},{"t":"赠道士","f":"五言绝句","c":["虎向深渊绕，龙归猛火蟠。","昆崙飞日月，奚但鼎中安。"]},{"t":"霜节堂","f":"七言绝句","c":["风冽前村有堕巢，何心寒苦自为高。","堪怜让杀閒桃李，只得虚堂两字褒。"]},{"t":"霜橘","f":"七言绝句","c":["半霜黄绿尚斓斑，笑指清芬数日间。","会得此中堪乐意，洞庭端合傲商山。"]},{"t":"藤枕诗","f":"七言绝句","c":["为爱江湖细雨声，短篷欹听买随行。","那堪老去便轻软，肯羡珊瑚与夜明。"]},{"t":"臞庵书事四首 其四","f":"七言绝句","c":["人生富贵尽浮云，何必须因不义分。","若有一丘能作主，更惭寇邓立功勋。"]},{"t":"臞庵书事四首 其三","f":"七言绝句","c":["曲涧斜穿竹最奇，岂容长夏有炎曦。","林深纵怯湖风猛，更为支筇立少时。"]},{"t":"臞庵书事四首 其二","f":"七言绝句","c":["老藤横路几星霜，骨相清坚寿自长。","敢惮侧巾方可过，折枝为子也何妨。"]},{"t":"臞庵书事四首 其一","f":"七言绝句","c":["畦丁相引绕园行，指说亭基不记名。","因想后湖题柱处，树林曾见作诗成。"]},{"t":"七夕","f":"七言律诗","c":["秋近疏飙未转凉，綵盘珠阁巳传觞。","佳期天上频逢节，却老人间未有方。","蟾魄嫩明情缱绻，鹊河斜界色沧浪。","瓜盘华锦空儿剧，祷旱于今仰圣皇。"]},{"t":"七夕前一夜翠樾堂设醮","f":"七言律诗","c":["矫首千寻古杏櫩，远林空处月钩纤。","龙蛇薮泽秋声起，牛女虚空夜气添。","满荡荷开从北看，危栏塔立向西瞻。","绿笺封事精忱达，髴郁天香羽袖沾。"]},{"t":"十月菊","f":"七言律诗","c":["幽芳何事独开迟，寂寞寒金照短篱。","老子樽罍方欠此，春风景物最相宜。","要随得煖南枝发，肯趁登高九日悲。","翻笑陶家门外柳，夜深零落舞腰肢。"]},{"t":"又呈坐客","f":"七言律诗","c":["天假南湖一段奇，宾朋胥会只论诗。","人生未老肯閒日，春色无边方盛时。","林外好山看独惯，尘中新事问宁知。","从来邂逅宜真率，花下杯传却莫迟。"]},{"t":"三月十四夜观月思南湖","f":"七言律诗","c":["期会纷言不到诗，拙哉前计只心知。","纵当吏散庭空后，争似山行水泛时。","柳影半笼明处路，苇声轻窣暗边篱。","波神擅此三更月，定讶今宵欠笛吹。"]},{"t":"与诸弟游天竺","f":"七言律诗","c":["出门残月带晨鸦，飞盖相从纵五花。","风绰败芦依岸老，水分洲渚抱山斜。","櫜鞬未遂书生志，钟磬聊寻衲子家。","何物最能舒望眼，晓云吹霁不成霞。"]},{"t":"山寺小憩","f":"七言律诗","c":["趋寺松杉夹径栽，解鞍流憩得莓苔。","尘昏金篆牌犹挂，灯暗纱笼殿不开。","老鹤就凉临古井，幽禽寻食下生台。","诗成漫记檐间柱，去矣何时复此来。"]},{"t":"山茶花","f":"五言律诗","c":["翠翼高攒叶，朱缨澹拂花。","来从山堑侧，开称画檐牙。","影薄谁停绣，香清似煮茶。","几多轻敛态，月动夹窗纱。"]},{"t":"山堂晚兴","f":"七言律诗","c":["小堂清占景无哗，不向阶前种俗花。","过雨家茶脱黄玉，近霜天竹缀丹沙。","静眠宁羡蚁来梦，孤坐屡谙蜂报衙。","万事一身安分定，关河休用发长嗟。"]},{"t":"书东迁褚氏壁","f":"七言律诗","c":["风晴舒望绿吹林，舣棹蒿田曲径深。","淳朴山川追古俗，萧閒林谷许幽寻。","籯金不必多留子，种德先须善用心。","动我耕耘平日兴，浊醪归缓肯辞斟。"]},{"t":"书事","f":"七言律诗","c":["剩喜居园野趣成，今春添得四桥横。","猿猴渐解擎书策，鹦鹉新能唤佛名。","酒旆静垂墙杏雨，茶铛閒试砌莎晴。","连年固自穷幽讨，新试频伽一两声。"]},{"t":"五日荥阳郡王饷酒","f":"七言律诗","c":["閒中滋味谙来惯，懒费心情为节辰。","丹篆但期诗祟去，红泥俄见酒壶新。","移船遣送随鱼信，洗盏开尝对鹤宾。","绝胜渊明过重九，东篱空伴白衣人。"]},{"t":"五月十六日夜南湖观月","f":"七言律诗","c":["良宵观月岂无人，未必能看到四更。","山载塔灯金笔立，水摇亭槛玉帘横。","歌从菡萏香中起，酒向玻瓈盏内明。","谁信南湖当暑夜，葛衣风透觉寒生。"]},{"t":"五用前韵咏丹桂花","f":"七言律诗","c":["遍看韶淑万花林，谁似秋风巧力深。","点注红泥千日酒，剪裁紫磨十分金。","色迷仙令疑勾漏，香醉姮娥忘藁砧。","莫把钓竿烟外去，珊瑚休道海中沉。"]},{"t":"五林方沈氏居","f":"七言律诗","c":["路转苍湾静者家，抱墙脩竹舞薝斜。","佛灯镜照无尽像，书馆池栽成行花。","粗有田园真可乐，不维车服更何加。","晚来清致因閒取，非故邀君一煮茶。"]},{"t":"以洞庭橘寄杨秘监","f":"七言律诗","c":["橘色浑如柿色黄，诚斋有句合分尝。","岂为都市颇难得，要是洞庭亲寄将。","雨露山中今有味，星辰天上旧无香。","遥知老监开奁处，为釂椒花雨一觞。"]},{"t":"以道次韵因再和二首 其二","f":"七言律诗","c":["顷年寻地喜初来，墙下松飘满径钗。","屈指五经寒暑候，教人一扫利荣怀。","南湖又共诗翁住，东寺须连单位排。","触景未尝瞒昧得，肯从颜氏学心斋。"]},{"t":"以道次韵因再和二首 其一","f":"七言律诗","c":["秋林何翅一般香，楚思无穷属野航。","不必再参庞老语，要须先会接舆狂。","青灯渐向韦编熟，白露初添玉井凉。","久矣荡除人我相，莫疑高尚鄙侯王。"]},{"t":"尤丈京丈和篇踏至四用前韵为谢","f":"七言律诗","c":["江南从识桂花林，岁岁逢秋属意深。","夜气未添承露掌，晓光先上辟寒金。","玉笙殿迥应留月，铁杵岩高不用砧。","争似吾家种流水，拥香亭榭绿沉沉。"]},{"t":"水仙花","f":"七言律诗","c":["鲤鱼程阔海茫茫，照眼琼标十二行。","矾弟梅兄同旧隐，风姨月姊特新妆。","湘滨人远难闻瑟，洛浦才高最断肠。","何似香严真实处，鼻端无窍著猜量。"]},{"t":"长至前夕书寄陆严州","f":"七言律诗","c":["铜炉熟火暖无烟，一盏清灯纸帐边。","迟睡颇如除夜景，新阳方幸好晴天。","诗成水阁梅堪折，信断山城雁不传。","莫待扁舟叙暌隔，归来身作紫微仙。"]},{"t":"代书回寄杨伯虎","f":"五言律诗","c":["僧舍匆匆别，飞花雨过春。","水村居自乐，城市懒尤真。","载酒青油舫，传书白锦鳞。","访君须及早，非是久閒人。"]},{"t":"写村舍壁","f":"七言律诗","c":["路转溪隅草色苍，烟霏云屋带渔乡。","鸡头叶老陂塘暗，狗脊花繁篱落香。","景物向人须品藻，太平无地不耕桑。","何时秋入丰年社，持蟹来听压酒床。"]},{"t":"冬日","f":"七言律诗","c":["半空飞雨整还斜，翳日游云散复遮。","七字吟情书柿叶，一年心事约梅花。","关门人识陶潜室，静坐自疑庞蕴家。","纸帐蒲龛方用事，更须何物作生涯。"]},{"t":"冬至日晓雪庭桂一枝著花戏成长句","f":"七言律诗","c":["居士归来百事嘉，木樨雪里也开花。","麸金一掬枝头小，药玉千沟屋上斜。","境界许奇非浪得，色香俱静更何加。","高寒似我休拈出，微笑从来少作家。"]},{"t":"冬至后五日约客晨往极乐精舍因寻梅湖山作诗纪事 其二","f":"五言律诗","c":["未苦撩清兴，骑驴故绕山。","松篁高下处，云日往来间。","要是从今后，休教枉却閒。","乌巾风弄影，画出我诗孱。"]},{"t":"冬至后五日约客晨往极乐精舍因寻梅湖山作诗纪事 其一","f":"词","c":["烟重山弥远，林高日倍鲜。","抱鸡趋野店，?水入冰田。","未有三冬雪，浑如二月天。","梅花应早慧，著眼竹篱前。"]},{"t":"出馀杭县","f":"七言律诗","c":["暑剧中宵枕屡移，夙兴犹得趁凉时。","平冲露气篮舆稳，遥杂星芒筱炬随。","触景有诗聊记述，为人无术漫驱驰。","须臾假寐谁惊觉，隔岸清风叫子规。"]},{"t":"出寂照行至书馆","f":"七言律诗","c":["茅屋鸡声过日中，热云蒸雨转无风。","形劳自背当年说，句快全誇近日工。","破院未成投宿计，枯田犹觊入秋丰。","情知必没扬雄宅，看竹何妨揖主翁。"]},{"t":"出德清县","f":"七言律诗","c":["天公有意作诗颠，入得苕溪未见莲。","先放水荭围半里，更将芦叶界平川。","明金扇日停苍渚，碧玉环山吐白烟。","非是老夫来领略，此中那有地行仙。"]},{"t":"北山早兴","f":"五言律诗","c":["出郭凉舆稳，山晨气自浓。","寺园逢水断，塔路过烟重。","啄木声穿竹，凌霄色映松。","世欢吾傥泥，那遂此从容。"]},{"t":"圣井亭","f":"七言律诗","c":["重到虚亭意豁然，望高容易觉秋天。","山连旷野全无水，树杂轻烟间有田。","极目几时忘去路，西风何日送归船。","残蝉更唤斜阳好，衬出金刚翠筱边。"]},{"t":"对月","f":"七言律诗","c":["景奇天遣助诗豪，意快惭无鍊句劳。","一夜月晖金盌出，万波风摆玉鳞高。","衣冠城里多新贵，酒脯船中自老饕。","未著丛书追笠泽，此行扶路且游遨。"]},{"t":"平望遇风","f":"七言律诗","c":["平望陂湖一望平，当年地志岂虚名。","微茫远树山同出，破碎层云日斗明。","更著百千寒雁叫，偏宜三四旅帆征。","疏帘揭起从风入，要洗频年郁滞情。"]},{"t":"归南湖喜成","f":"七言律诗","c":["路转斜桥似梦醒，拥衾摇兀亦身轻。","知期岸鹊如相语，匿笑邻翁欲斗迎。","见处青山还委么，遮回居士太呆生。","矮篱半路寒毬树，新种浑如旧种成。"]},{"t":"正月八日喜霁","f":"七言律诗","c":["未春天气已佳晴，病起光风满意明。","竹色舞帘金翠活，鸟声穿户角宫成。","黄麻天上登周召，浊酒林间慕绮荣。","从此寻芳绕阡陌，野翁相遇诧时平。"]},{"t":"正月三日同诸亲从叔祖阁学登宁寿观东西山寻至邻园次叔祖韵","f":"五言律诗","c":["超旷欣便静，纷哗厌处浓。","客亲非外约，地胜适新逢。","诗兴骖黄鹤，仙情寄赤松。","烟平千万户，此处认歌钟。"]},{"t":"永嘉张仲思相士过访坐间索诗","f":"五言律诗","c":["便静非形色，相逢子独知。","功名槐蚁话，文字壁鱼痴。","剩取朝贤誉，何须隐者诗。","南湖鸥正狎，休误凤凰池。"]},{"t":"玉照堂观梅二首 其二","f":"七言律诗","c":["未办当春句法工，坐来花下泥春风。","山高水远须人领，玉洁珠光喜日烘。","越女信知天下白，屈平那是泽边穷。","明朝风雨从教有，老眼今年已不空。"]},{"t":"玉照堂观梅二首 其一","f":"七言律诗","c":["绝怜一见一番新，短直长斜意总真。","绕屋便能云态度，问春谁更雪精神。","栽花十亩犹嫌少，与我多生定是亲。","为惜生香怕閒却，折归聊当散花人。"]},{"t":"立春日访梅裴氏园","f":"七言律诗","c":["下马东风恰到来，午烟沙际日烘开。","长松寂历寒声少，远柳葱茏绿意回。","零落欢游逢故地，夤缘幽胜逐深杯。","湖边不使侬先咏，枉却今年处士梅。"]},{"t":"买书","f":"五言律诗","c":["自笑从来癖，诗书满屋藏。","不充饥鼠喙，即饱蠹鱼肠。","插架牙签整，开编竹简香。","他年林下去，谁与记山房。"]},{"t":"伏日","f":"五言律诗","c":["未晓雨先骤，过朝风更鲜。","谁知初伏日，全是早秋天。","洗盏尝新酒，临池摘嫩莲。","平生丘壑意，不受暑寒迁。"]},{"t":"再游 其一","f":"七言律诗","c":["晓日晴岗路未分，昔年钟磬隔林闻。","龙归古洞千岩雨，人卧空山半榻云。","异草灵苗交晚翠，野兰芳芷杂秋芬。","何时得似山中鹤，脱却鸡群友鹿群。"]},{"t":"刘子履少卿挽辞二首 其二","f":"七言律诗","c":["释和书上巳经年，敌骑南来果犯边。","太息龟灵成底事，漫闻鸿宝得家传。","平生喜踏天山雪，晚岁愁看瘴浦烟。","务实褒称曾未泯，不须凝恨入重泉。"]},{"t":"刘子履少卿挽辞二首 其一","f":"七言律诗","c":["气盖两峰蚤食牛，堂堂声誉冠诸刘。","直言不愧上方剑，妙句常轻万户侯。","仙药了无金鼎效，梦魂空绕玉关秋。","当时若假三千骑，岂但区区活泰州。"]},{"t":"名新酿曰白鸥波以一尊送佑圣观刘高士","f":"五言律诗","c":["酒熟将何字，白鸥波正如。","一瓢谁合饮，高士观中居。","汗漫涵无象，鸿濛洽太初。","醒来松户晓，应念臭于帑。"]},{"t":"回渡荷叶浦","f":"七言律诗","c":["宿雨惊眠变早凉，喜成风便放归航。","山云野树水墨暗，芦叶荷花文绣香。","藉枕冰藤醒倦思，打帘珠浪发清狂。","天围平浦方宜眼，便腹飞帆莫太忙。"]},{"t":"因过田倅坐间得姜尧章所赠诗卷以七字为报","f":"七言律诗","c":["京廛舆马竞扬埃，何碍骚人独往回。","我住水边奚自识，诗如云外寄将来。","一从风袖携归看，屡向松亭静展开。","应是冰清逢玉润，只因佳句不因媒。"]},{"t":"因过张郎中识孙才翁教授时徐衡仲亦在坐成四韵送呈","f":"五言律诗","c":["邂逅如相约，新交会旧知。","轩窗浑未暑，宾主总能诗。","小草浮冰楮，初篁映锦葵。","星郎风韵杀，我辈盍幽期。"]},{"t":"守岁","f":"七言律诗","c":["寒缸孤照听更迟，情绪斟量睡却宜。","春向岁前三日到，老缘头上二毛知。","朱泥逐疫烧灵药，桃板书符换旧诗。","但愿明年更閒散，无灾无难复何疑。"]},{"t":"安乐泉亭上午憩","f":"五言律诗","c":["脩竹有风处，道人无事时。","诸公难入眼，不用总如眉。","得价婆娑重，投閒懒散宜。","三年何足道，坚判百年期。"]},{"t":"安溪山间寻桂得之","f":"七言律诗","c":["心期经岁只秋芳，况有溪山近好凉。","天宇荡开暄浊意，岩花催就泬寥香。","招寻拟把深枝折，爱护休令背蕊伤。","三五冰轮行散影，仙凡同异要平章。"]},{"t":"安溪晚泊因到无净院","f":"七言律诗","c":["十丈亭桥稳踔溪，斜阳红滟入船低。","枯筇径过荒街北，静院深寻破庙西。","游伴苦无成独笑，物情谙遍任难齐。","归时早是星烦出，影漾波痕上下迷。"]},{"t":"戏呈郑去华县丞","f":"七言律诗","c":["叠破当年御赐袍，饱看人钓六灵鳌。","行藏虽似少中节，识趣不妨依旧高。","入梦傅岩初岂意，上书曼倩本徒劳。","浮生万事天都了，爱惜君才祝善刀。"]},{"t":"戏题","f":"七言律诗","c":["人前一语撞翻墙，直气西秦本故乡。","雪野射麋轻队马，杏园移象矮交床。","诗忙渴砚酒磨墨，睡足趄廊花夺香。","矫揉尽归官样去，有时閒笑错商量。"]},{"t":"戏题故袍","f":"七言律诗","c":["垂髫便衣绿荷衣，两见龙飞圣主时。","举世恩荣俱合换，唯吾忧患只该披。","收藏尽好随腰带，提掇应堪傲鬓丝。","试使著来门外立，精神犹胜似钟馗。"]},{"t":"早饭庵中次张以道韵","f":"五言律诗","c":["岂是幽人眼，从来可惯山。","有时才得见，觅句不曾閒。","野日光尤暖，溪梅信尚悭。","饭馀行便去，休待暮云还。"]},{"t":"曲廊","f":"七言律诗","c":["曲廊桐树绿阴阴，檐佩风来奏玉琴。","但有疏帘知独立，更无尘事恼閒心。","雪霜鬓畔谁能免，城府胸中枉自深。","二六时辰真快乐，坐禅才罢即行吟。"]},{"t":"有怀参政范公因书桂隐近事奉寄二首 其二","f":"七言律诗","c":["迂疏那可作治中，閒事归来却不慵。","晓炷佛香聊作观，晚投社饮亦称侬。","荷衣制就身宜著，菰米收成手自舂。","最是今春多伟绩，万丛兰四百株松。"]},{"t":"有怀参政范公因书桂隐近事奉寄二首 其一","f":"七言律诗","c":["石湖仙伯住吴门，事业文章两足尊。","南北东西曾遍历，焉哉乎也敢轻论。","桂园柳色金丝织，笠泽桃花锦浪翻。","小大风烟俱自适，鹪巢终莫拟云鲲。"]},{"t":"杂兴三十九首 其十七","f":"五言律诗","c":["圣道由书传，秉畀火于秦。","汉兴反秦暴，见儒犹骂嗔。","董子惟有志，耿耿谁与陈。","使时三策行，焉老诸侯宾。"]},{"t":"次以道荷叶浦","f":"词","c":["向来曾爱叶田田，落日荷花拥棹前。","霜冷不移鱼世界，苇残聊作雁家缘。","诗狂顷刻成三首，懒病中间接四边。","除此今朝无别事，与君相就乐?船。"]},{"t":"次张以道韵","f":"七言律诗","c":["无愁便是乐无涯，看破纷纷眼里花。","旋洗杯盂将酒试，重糊窗户把风遮。","丹房火鼎频添水，衣匮香炉就焙茶。","判却一生閒理会，共君难数第三家。"]},{"t":"次夜月色复佳游霞川锦池二首 其二","f":"七言律诗","c":["画桥烟重柳垂垂，露湿衣裳透始知。","丹桂花香墙畔起，水荭枝影席间移。","思量究竟都如梦，恋著休閒煞不痴。","夜半江潮声正熟，归来才是欲眠时。"]},{"t":"次夜月色复佳游霞川锦池二首 其一","f":"七言律诗","c":["倚栏看月兴难平，载酒还须入涧行。","竹顶有时翻鹊翅，草根随处闹虫声。","城中岂是无人赏，船里何曾卧地撑。","游遍一池心未足，乱荷丛底听三更。"]},{"t":"次武子韵","f":"词","c":["宇内张夫子，诗如孟浩然。","安心从太末，借屋近平泉。","眼里弹冠手，生来种芋田。","相投忽离席，佳月恋?船。"]},{"t":"次韵王耘之","f":"七言律诗","c":["白汗翻浆九市人，清风谁似此论心。","壮游淮上官声起，重会都城句法深。","久矣求才胶柱瑟，老来逢事不徽琴。","漫湖又见香荷发，煮饼须同近寺林。"]},{"t":"次韵王耘之秋兴二首 其二","f":"五言律诗","c":["多士宁王室，中宸梦傅岩。","如何两京客，犹挂五湖帆。","落落云松节，飘飘霜叶杉。","深藏草檄手，端欲取殽函。"]},{"t":"次韵王耘之秋兴二首 其一","f":"五言律诗","c":["妙墨真连草，清辞角应商。","襟期容汗漫，兴致入苍茫。","派自王摩诘，才分马子长。","宦途休叹滞，眉宇见新黄。"]},{"t":"次韵杨廷秀左司见赠","f":"五言律诗","c":["愿得诚斋句，铭心秪旧尝。","一朝三昧手，五字百般香。","弦绝今何苦，衣传拟自强。","草玄非近效，举世漫匆忙。"]},{"t":"次韵陈秀才","f":"七言律诗","c":["规模浑是野人居，剪结苍松荫屋除。","閒把欹眠酬懒架，静便徐步当安舆。","青精饭好终延老，紫石潭空总付渠。","玩世从来畏人觉，他年方信此心初。"]},{"t":"次韵叔祖阁学秋兴","f":"七言律诗","c":["岁序推流感世浮，乐閒宜早向农畴。","修梧绿减俄过夏，短发丝添剩得秋。","千古是非归啸傲，一门酬唱胜交游。","祗因名句多难数，常笑区区赵倚楼。"]},{"t":"次韵叔祖阁学题逸村亭壁","f":"五言律诗","c":["桥迥有牛过，村深无马嘶。","哨风惊客袂，膏雨慰耕犁。","游目花通野，吟情絮著泥。","幽坊惬虚眺，况复见新题。"]},{"t":"次韵周昭礼见寄兼约观园梅","f":"七言律诗","c":["沙头晴了便回春，巳觉青蘋媚煖津。","但课浇畦园内叟，何心说剑里中人。","超情耐久宁拘远，合处无多颇复伸。","待得梅开醉香海，健呼重看老精神。"]},{"t":"次韵奉酬张野夫见赠","f":"七言律诗","c":["谋身堪笑若舂锄，甓社栖寒水满湖。","近寺偶成莲社似，为园非效辋川图。","清樽酒好诗中圣，古冢珠存念大儒。","久矣自求无所用，喜君能好柏楸株。"]},{"t":"次韵罗端规二首 其二","f":"五言律诗","c":["雪窗吾畏友，称誉满中边。","往矣非乔木，生乎仗老天。","肯来丹桂里，须醉白鸥前。","百计安流好，纷纷急水船。"]},{"t":"次韵罗端规二首 其一","f":"五言律诗","c":["世态从渠变，前山只么新。","关门便懒退，遇事少躬亲。","和我诗何益，知公道不贫。","两旬才识面，枉是自由身。"]},{"t":"次韵寄斋赠竹居","f":"五言律诗","c":["振俗还风雅，乾坤觅句中。","夔皋渠合遇，郊岛我甘同。","浩荡投鸥水，清和翻燕风。","相投两无语，声远莫摩空。"]},{"t":"次韵答曾司法","f":"五言律诗","c":["精神由日就，格律忌雷同。","我匪从它入，君应自此工。","多岐怜世路，力学振家风。","莫易朱弦绝，千年论最公。"]},{"t":"次韵答潘茂洪桂花见怀","f":"五言律诗","c":["藉使音书少，何妨好尚通。","看花虽各自，觅句却相同。","嚼蕊晨烟里，搴枝夜月中。","亦曾湖上坐，香底水精宫。"]},{"t":"次韵酬张仲思高邮见寄二首 其二","f":"五言律诗","c":["便欲相寻去，山光看水光。","野航因挟策，春韭自炊粱。","踽踽吾才短，翩翩子意长。","文翁他日誉，不但劝农桑。"]},{"t":"次韵酬张仲思高邮见寄二首 其一","f":"五言律诗","c":["春来慵把酒，间日伴僧斋。","风雨梅花梦，溪山老子怀。","有人非吏俗，同好任天涯。","归上青云日，幽期孰与偕。"]},{"t":"次韵酬杜材卿","f":"七言律诗","c":["楼寒鹤骨旧竛竮，别后溪山梦不扃。","世事益知推去好，鬓毛浑减向来青。","诗篇又见声谐律，才兴何疑刃照硎。","愁里不妨同茗酌，古梅园种百龙形。"]},{"t":"次韵酬杨伯子兼呈诚斋 其一","f":"五言律诗","c":["我固有诗癖，怜君尤苦心。","自闻非为俗，异处却同音。","病后閒方乞，湖边秋渐深。","排门听车骑，相与话幽襟。"]},{"t":"次韵酬杨伯子兼呈诚斋 其二","f":"五言律诗","c":["见说聪明早，童年便与玄。","细看今日句，宛似乃翁篇。","家谱无他姓，文星聚此边。","何须待千首，一首已堪传。"]},{"t":"次韵酬陈伯冶监仓","f":"七言律诗","c":["小筑才成赐也墙，传家那是钓徒张。","非求世上人看好，但要閒中句律昌。","成阵游鯈波上暖，打团飞蝶菊初荒。","邻翁莫厌频相遇，会见翱翔入未央。"]},{"t":"次韵酬郑唐老见寄","f":"七言律诗","c":["黄叶归根静不风，回塘雪后正浟溶。","山林有分吾当去，簪绂方兴子未慵。","点检寒荣梅又动，思量暖事李将秾。","桥南水北来还往，露布诗篇不必封。"]},{"t":"次韵酬唐老见赠","f":"七言律诗","c":["菊边莎处坦平居，危径吾知勉覆车。","争似即时三盏酒，何曾得力半行书。","鱼乡坐占真清矣，蜂户行看亦要如。","过我不疏君始信，向来犹恐压荒墟。"]},{"t":"次韵酬喻工部雪中见怀","f":"五言律诗","c":["坐厌增冰地，遥思胜热城。","忘名全道用，远俗养诗情。","枕病怜幽独，心交阻合并。","晴春开径在，自断学渊明。"]},{"t":"次韵酬曾无逸宗教 其二","f":"五言律诗","c":["地秀溪通邑，山高寺矗云。","望殊惊乍见，景胜厌前闻。","鸡犬人家乐，风烟钓艇纷。","奔程船径过，虽雨未西曛。"]},{"t":"次韵酬曾无逸宗教 其一","f":"五言律诗","c":["自识閒中趣，常嫌闹处行。","湖山真富贵，花鸟小声名。","有客金兰好，贻诗徵角鸣。","相期耐霜露，斯事岂凡情。"]},{"t":"次韵酬新九江使君赵明达二诗仍送自制香饼白鸥波酒 其二","f":"七言律诗","c":["岁晏怀人水一湄，归鸿去雁各参差。","寒风不解频吹梦，疾置何妨数寄诗。","酿酒改名聊济胜，和香因谱更求奇。","路遥不暇多瓶送，一炷同参日渐迟。"]},{"t":"次韵酬新九江使君赵明达二诗仍送自制香饼白鸥波酒 其一","f":"七言律诗","c":["纷纷金佩与瑶环，骨相如吾敢妄攀。","居处何曾离城郭，襟期终不负湖山。","杉旁试履拖云湿，石上敲钩破藓斑。","冲晓樵童便来往，思量谁是我投閒。"]},{"t":"次韵酬潘茂洪见寄","f":"七言律诗","c":["怀人非特为能诗，襟抱如君坦复怡。","三径许时无地觅，一生高处只天知。","江湖老梦疏篷惯，灯火凉秋细字宜。","此兴未尝殊往岁，水边唯欠咏黄葵。"]},{"t":"次韵谭德春见寄","f":"七言律诗","c":["端的公宜语个中，对山萦碧照清冬。","鹤毛雨渍苔钱古，蚁穴风堆橡斗重。","已乏尖新陪世话，断无阔匾拆书封。","一轩煨芋方题榜，时过松扉慰我慵。"]},{"t":"次韵潘茂洪春日书怀","f":"七言律诗","c":["东风渐放柳遮门，隔水人家聚似村。","渔艇远来誇甫里，僧邻閒过讲慈恩。","花繁惯识蜂情性，昼静初闻燕语言。","病起适逢春正好，莫教诗思却尘昏。"]},{"t":"汎锦池霞川呈张以道二首 其二","f":"七言律诗","c":["戏选婵娟结伴来，画桥低处侧鸾钗。","娲簧静试醒松响，鲁酒聊倾旷荡怀。","万事亦须从使便，百年无过任天排。","怜君近许同心友，分取湖光到竹斋。"]},{"t":"汎锦池霞川呈张以道二首 其一","f":"七言律诗","c":["夕风轻飏一池香，遥为荷花泛短航。","俗子几曾贪韵胜，閒人嬴得放清狂。","幽栖野鹤林松黑，乱扑流萤水叶凉。","会取渭川当日意，不将终老俟周王。"]},{"t":"灯夕","f":"七言律诗","c":["插花呼酒少年场，烂赏花灯十里香。","璧月当天星纬少，珠帘排户乐声长。","非缘风景今殊昔，自是情怀老不狂。","赢得安禅心似水，碧琉璃照佛龛旁。"]},{"t":"竹轩诗兴","f":"七言律诗","c":["柴门风捲却吹开，陕径初成竹旋栽。","梢影细从茶椀入，叶声轻逐篆烟来。","暑天倦卧星穿透，冬昼閒吟雪压摧。","预想此时应更好，莫移墙下一株梅。"]},{"t":"约斋西窗先有垂柳腊后四日辟地增植花数十辈","f":"七言律诗","c":["经年规画种酴醾，柳际春将一再归。","蔓草藩墙才放远，海棠桃杏得成围。","连宵冷月知予乐，数日条风挟鸟飞。","尽写前人题品句，诵声时撼绿窗扉。"]},{"t":"老笔赠铦上人二首 其二","f":"五言律诗","c":["已事殷然急，江湖第一流。","才高楼五凤，伎进刃全牛。","可惜梅花节，忙回竹叶舟。","老师应赏棒，碑巨压东州。"]},{"t":"老笔赠铦上人二首 其一","f":"五言律诗","c":["握手四年别，满心千偈禅。","清灯才软语，新雪尚幽眠。","了了翻身诀，寥寥断臂缘。","我怀吾自会，恶句莫多传。"]},{"t":"自叹","f":"七言律诗","c":["居士年来更觉痴，竹梢云过望移时。","晓窗倦栉犹思梦，夜榻忘眠尚改诗。","匹马未能随李广，一丘端欲效元规。","客谈休讶无心对，贪看蜘蛛结网丝。"]},{"t":"自咏","f":"七言律诗","c":["南湖老子太汗漫，第一生来懒做官。","钱物用多常是解，权门路便不曾钻。","红裙遣去如僧榻，白发梳来称道冠。","若没祖财教饭饱，定应饿作壁鱼乾。"]},{"t":"自料","f":"七言律诗","c":["自料躬耕体力微，他年为圃雅相宜。","植茶要是依桑荫，种芋先须纳豆萁。","药爱金樱长林薄，花因木槿作藩篱。","祗应分绝陶朱富，不愿鱼繁六亩池。"]},{"t":"自横山归偶成","f":"七言律诗","c":["杖藜如向碧空行，路转松杉面面声。","遗庙香残人少到，古台仙去草閒生。","都缘世念多时绝，不但尘襟逐境清。","却上小舆归寓舍，晚峰明暗紫烟横。"]},{"t":"舟行","f":"七言律诗","c":["经夕舟行路未赊，不须寒梦早还家。","云连冈势通平野，雨溢滩声走乱沙。","蘋蓼静怜鱼世界，菰蒲遥想雁生涯。","玄真便合苕溪隐，莫待摧颓两鬓华。"]},{"t":"行次季村","f":"五言律诗","c":["破衣鸣蓬雨，迎晨捩柁风。","擘茭溪饭白，锻铁店炉红。","于役多无定，于心少所同。","船人探蟹室，持寿觅诗翁。"]},{"t":"行次莺脰湖","f":"五言律诗","c":["震泽匆匆过，胥塘渐渐来。","风高多罨岸，船侧屡翻杯。","积草摊渔网，疏林聚客桅。","景逢宜急写，句过恐难裁。"]},{"t":"行近湖州不果入城寄王成之使君","f":"七言律诗","c":["江左风流燕子家，有人襟度渺云涯。","讴歌冯翊今分竹，词藻西垣旧判花。","相望每居形迹外，投閒常动别离嗟。","因行一见还成阻，谁谓人遐自室遐。"]},{"t":"许深父送日铸茶","f":"七言律诗","c":["短笺欣见小龙蛇，谏省初颁越岭茶。","瓷缶秘香蒙翠箬，蜡封承印湿丹砂。","清风洒落曾谁比，正味森严更可嘉。","堪笑云台方忍睡，强行松径嚼新芽。"]},{"t":"过凤山高氏以榴实荐酒","f":"七言律诗","c":["湾洄绿处得鸡声，俯槛山宜柳外明。","京洛涨尘衣半黑，邯郸炊黍梦曾惊。","榴皮就为翁题好，竹叶能邀我兴成。","办此一廛归老计，弄孙相对说春耕。"]},{"t":"过红城子","f":"七言律诗","c":["阔港旁边狭港横，大桥侧畔小桥平。","吠人黄耳穿篱走，唤子青裾出户迎。","寒日树枯山得势，顺风樯稳浪无声。","自知吟写红城景，不让丹青笔作城。"]},{"t":"过冷泉","f":"五言律诗","c":["未喜亭阴坐，先贪树畔行。","溪浑因雨瀑，岩近得风清。","一饭幽人福，三杯太古情。","尚须冰月挂，来放雪涛倾。"]},{"t":"过杨伯虎即席书事","f":"五言律诗","c":["四面围疏竹，中间著小台。","有时将客到，随意看花开。","拂拭莓苔石，招携码碯杯。","昏鸦归欲尽，数个入诗来。"]},{"t":"过临安海会寺东长桥有怀苏文忠公","f":"七言律诗","c":["竦踊峰环碧玉城，乱蝉争送夕阳明。","飞桥预快登山足，坏塔遥增吊古情。","陈迹几年惊梦幻，清文随处振英茎。","胡床等到三更看，閒过桐乡或驾鲸。"]},{"t":"过湖至郭氏庵","f":"五言律诗","c":["山色棱层出，荷花浪漫开。","只如平日看，自喜此时来。","杨柳侵船影，蜻蜓傍酒杯。","僧庐须过夜，城禁莫催回。"]},{"t":"过翔鸾院留题僧房","f":"五言律诗","c":["频年虽并住，今日偶能来。","水槛因莲设，风窗为客开。","诗凡惭鲍谢，社近忆宗雷。","莫问通衢隔，轻舟自往回。"]},{"t":"伴书回寄建康张总卿","f":"七言律诗","c":["湖上初晴擅晓凉，一缄俄坠读书床。","月卿星使年年忆，雪白兰薰字字香。","闻道江边勤叱驭，也知鸥外静鸣榔。","新君未识诗人在，早觐枫宸荷紫囊。"]},{"t":"余家兄弟未尝久别今夏送平父之官山口冬仲朔又送深父为四明船官因成长句","f":"七言律诗","c":["遵渚霜鸿散漫飞，江天分序益凄悲。","孤生只合群居乐，半岁那禁两别离。","发轫固知期远到，望船犹怕独归时。","书来岂是寒暄语，尽写衷情慰渴饥。"]},{"t":"即席次吴季行韵","f":"五言律诗","c":["昔逢欣把袂，三叹说吴钩。","共醉虚堂晚，还兴故国愁。","花黄思靖节，鬓绿傲浮丘。","世济王门业，洪流万斛舟。"]},{"t":"即席次韵器之相赠","f":"七言律诗","c":["会閒须是莫论年，直把浮生付且然。","桂隐欲为山宰相，漆园曾是地神仙。","看抄妙句行催酒，更向清流卧泛船。","但喜相从得真乐，何心玩世学前贤。"]},{"t":"即席次潘茂洪韵","f":"七言律诗","c":["我恨填胸三斗尘，略无警句可留春。","烟云空外吹成鹤，梅杏枝头长就人。","但解时中心独废，自然随处乐常新。","诸公要识居园法，第一先教懒是真。"]},{"t":"呈毛崇夫司直","f":"七言律诗","c":["春到深时味更长，草晴胜似杂花香。","清阴渐次迷天绿，白发依稀照领光。","逐妇墙鸠知雨近，生儿梁燕补巢忙。","擘笺谩记今朝景，朝路归时肯易忘。"]},{"t":"呈吴居甫待制","f":"七言律诗","c":["挺挺风规轶辈流，肯因官誉掩清脩。","南宫妙画多时见，北固新篇去岁收。","每念小人同话此，曾知閒客到门不。","平生自笑迂疏甚，趋造才频更觉愁。"]},{"t":"呈张左曹郎中","f":"七言律诗","c":["持节江湘公去久，浙西风月我孤吟。","相逢未叙三年话，此事先抛一寸心。","风调不因通宦汨，世涂尤见故情深。","随人一错终能复，林墅应劳得得寻。"]},{"t":"呈曾仲躬侍郎","f":"七言律诗","c":["公道欣从禁路开，世家今有伟人来。","共推掌学文清手，突过谈兵杜牧才。","老眼知人明月镜，时情荐士冷秸灰。","诗章活法从公了，要使诸方听若雷。"]},{"t":"园中梅有开者寄呈当涂叔祖","f":"七言律诗","c":["春到林梅得重权，首冬疏萼巳争先。","移栽尚记陪深斝，静看因思觅近篇。","佐世勋庸金鼎味，贪閒怀抱竹篱烟。","临风欲寄横斜去，梦绕江城暮角边。"]},{"t":"园桂初发邀同社小饮","f":"五言律诗","c":["故故论年赏，新看惜未多。","一香参众树，千月下纤娥。","今雨胡能阻，秋虫亦复歌。","有情毋吝醉，斯世合婆娑。"]},{"t":"改旧诗戏成","f":"七言律诗","c":["不作新诗只改诗，当家功用亦几希。","全牛迎刃未能解，六鹢遇风先退飞。","欲脱规模还似旧，枉教躯干不曾肥。","何如尽付红炉火，免使群公说是非。"]},{"t":"时贤有爵高名重而不自由者再念閒居之可乐为赋长句","f":"七言律诗","c":["多幸因愚得养恬，林扃风变陡寒天。","杯传蕉叶温成酒，袄织梅花软入绵。","经室炉添羊胫炭，道床屏护鹧斑烟。","遥思病叟头如雪，冒冷遐征想自怜。"]},{"t":"杨仲子携诗见过次韵酬赠并呈诚斋二首 其二","f":"五言律诗","c":["爱水移居宅，行藏岂但迂。","若非风月管，枉伴竹松臞。","野服常宽带，芒鞋亦断絇。","请君看此老，堪作贵人无。"]},{"t":"杨仲子携诗见过次韵酬赠并呈诚斋二首 其一","f":"五言律诗","c":["老监过陈实，贤郎似窦群。","共将奇句了，不许外人分。","访我三竿日，萦帘一炷云。","当家相见处，那此世情欣。"]},{"t":"杨伯子见访惠示两诗因次韵并呈诚斋 其二","f":"五言律诗","c":["别去常关梦，书来意已强。","那看多竹地，相对两绳床。","壮志霜空鹘，禅心古庙香。","糠炉熟黄独，待子数分尝。"]},{"t":"杨伯子见访惠示两诗因次韵并呈诚斋 其一","f":"五言律诗","c":["自作诗中祖，翁难子更难。","波澜千偈阔，光焰九霄寒。","觅著由来远，成时自好看。","头头见成字，谁道要吟安。"]},{"t":"杨伯子过访翌日以两诗见贻因次韵答 其一","f":"五言律诗","c":["晴色今朝好，春光恰半头。","波情如钓渭，圃事胜封留。","瘦觉中黄合，閒宜大白浮。","无端同志侣，相过结诗愁。"]},{"t":"杨伯子过访翌日以两诗见贻因次韵答 其二","f":"五言律诗","c":["句业诚渊海，愚方一苇航。","空成由也瑟，难应女娲簧。","拟易乾坤别，传家父子香。","整翰从此去，拭眦望朝阳。"]},{"t":"杨伯时李子永潘茂洪同游安福寺诗","f":"七言律诗","c":["湖滨初试暮春衣，绿径钟残到寺迟。","二月梅花还傍竹，一时游客总能诗。","横栏著砚争濡墨，断石缘蒲静看池。","莫问邻亭是谁筑，山园持酒本幽期。"]},{"t":"杨秘监补外赠送","f":"五言律诗","c":["止是寻常月，今宵不爱明。","江边有归客，都下减诗情。","上自怜公直，人知暂此行。","贤郎先返舍，应喜候门迎。"]},{"t":"泛湖","f":"七言律诗","c":["駮云飞去见晴岚，叠巘平湖影共涵。","景与新诗争上下，天将真赏冠东南。","频来但觉如初到，得侣何妨纵剧谈。","归路一弯明月好，闹花风里跃华骖。"]},{"t":"灵源精舍小憩旧名龙泉有古井极甘洌","f":"七言律诗","c":["姑恶声催雨不来，暑云空际只崔嵬。","投鞭得地古佛刹，看竹满窗风叶堆。","百岁可堪轻日月，一官才得便尘埃。","清泉酌罢犹贪恋，更瀹松黄当茗杯。"]},{"t":"牡丹","f":"五言律诗","c":["分数论春物，都应让牡丹。","几枝单叶紫，满担夕香寒。","除我知心切，从人得句难。","肯辞回棹日，多瓣剪来看。"]},{"t":"纳凉至夜深","f":"七言律诗","c":["积潦斜阳忽射阶，夜深穿树雨还来。","披襟径放清凉入，倚扇微教懒困催。","出草乱萤时自照，叫空孤鸟暗飞回。","贪吟四鼓犹妨寝，除此人间念总灰。"]},{"t":"芦山长老慧举见访约游其临平庵居自号云邱草堂因赠四韵","f":"七言律诗","c":["此客南湖不易逢，几年尘外愿相从。","风流前辈亲曾识，兴寄高情老未慵。","行柳映门宜著舫，青灯同坐到闻钟。","稻畦莲渚临平境，何幸同师觅旧踪。"]},{"t":"苍寒堂","f":"七言律诗","c":["短桥斜路入松林，何止能销利欲心。","眼悟一真清净色，耳通千古泰和音。","尺量梢影邀僧记，竹护根茎恐鹤侵。","莫讶塼炉多宿火，春晴犹似处云深。"]},{"t":"连日雪未能多曾无逸见惠二首遵欧苏律禁体物语及用故事走笔次韵 其二","f":"五言律诗","c":["待伴犹虚夜，羞明或遇朝。","但依歌袖舞，休向鬓丝飘。","有句清堪比，令人意自消。","暖寒林下具，相就可须招。"]},{"t":"閒步游紫极观","f":"七言律诗","c":["青惜高杉觅望宽，仙庐幽占路纡盘。","边花制古装门榜，老桂枝拳倚醮坛。","颜色不同轻紫绶，精神常在慕黄冠。","蜂巢蚁垤非吾乐，终买云扃种术餐。"]},{"t":"閒课","f":"七言律诗","c":["居閒投课孰为优，似此工夫尽不愁。","量涧打船轻似盏，转墙开径曲如钩。","巳令山圃收黄犊，又盖湖亭记白鸥。","春水画桥桃四百，新年那羡武陵游。"]},{"t":"卖花","f":"七言律诗","c":["种花千树满家林，诗思朝昏恼不禁。","担上青红相逐定，车中摇兀也教吟。","虽无蜂过曾偷采，犹恐尘飞数见侵。","应是花枝亦相望，恨无人似我知音。"]},{"t":"卧疾连日殊无聊赖客有送二省闱试题者因成四韵","f":"七言律诗","c":["春恨都缘少得晴，雨声浑是落梅声。","新愁多病易投隙，薄命壮怀难抗衡。","人世只宜常放逸，杏花多爱逼清明。","青袍白纻纷然梦，自笑生来入念轻。"]},{"t":"叔祖国学座间请观诗编因赋","f":"七言律诗","c":["出门何许会初心，家有师儒是学林。","画古更因金印伟，书丛方称锦堂深。","朱橙荐酒随冬蟹，翠蔓披墙引暮禽。","每幸酸咸得同嗜，可令倾耳阙韶音。"]},{"t":"命鹿","f":"五言律诗","c":["双鹿林泉友，新居后我成。","角低方长旺，斑嫩末分明。","濯濯菰塘晚，呦呦草径晴。","仙畴吾种玉，汝辈耦而耕。"]},{"t":"夜半浴","f":"五言律诗","c":["浊热不成睡，起看宵过中。","繁星珠结网，片月玉为弓。","赋鹊情何有，驱蚊计颇穷。","犹欣汤浴后，肤受绿蘋风。"]},{"t":"夜自叔祖北园归","f":"七言律诗","c":["夕霭生凉竹径迂，快风吹马出通衢。","疏星落落连城阙，击鼓阗阗杂笑呼。","竟日浪追河朔饮，几时真在辋川图。","归来小憩松棚下，绕烛飞虫索扇驱。"]},{"t":"夜坐示客","f":"五言律诗","c":["身世长歌里，于今得好朋。","露阶秋到竹，风屋夜吹灯。","菱芡供馋口，图书伴曲肱。","头颅知自揣，顾影笑鬅鬙。"]},{"t":"夜饮呈叶司户 其二","f":"五言律诗","c":["偻指抠衣日，于今岁六移。","步趋徒愿学，忧患亦何为。","窗晓鸦同起，天寒雁引悲。","依仁方再幸，小耐了康时。"]},{"t":"夜饮呈叶司户 其一","f":"五言律诗","c":["俗薄交难古，心亲话许深。","更长银烛夜，院静石云阴。","冷梦多孱骨，修程费老襟。","松壶梅并插，投醉且高吟。"]},{"t":"夜宿华藏寺","f":"七言律诗","c":["苍桧阴阴未掩门，閒来吹鬓一飞蚊。","香腾广殿游云合，灯绕长廊列宿分。","般若心华方照耀，毗耶宝雨自缤纷。","世缘即是栖禅境，居士何尝别见闻。"]},{"t":"奉寄淮西总领张少卿并呈建康留守章侍郎二首 其二","f":"五言律诗","c":["别来秋易过，幽桂两番开。","去岁人同赏，今宵梦自回。","飞云遥楚岫，斜照直秦淮。","地念曾游处，春行或许陪。"]},{"t":"奉寄淮西总领张少卿并呈建康留守章侍郎二首 其一","f":"五言律诗","c":["湖隐门连草，宗盟肯屡寻。","长才明主眷，直道古人心。","又引皇华去，谁怜白发侵。","官居兼静乐，贤帅复朋吟。"]},{"t":"姑苏怀古","f":"词","c":["昔年宫殿雨苔荒，花径无人采旧香。","宰噽若能容国士，西施那解误君王。","轻寒客子垂双袖，落日啼乌下女墙。","成坏不将供一笑，争如烟外?渔郎。"]},{"t":"官舍梦归南湖","f":"七言律诗","c":["林野相望不隔关，梦魂径到岂为难。","恍如天上飞升客，忘却人间走俗官。","嵓桂直通笼鹤槛，水荭斜倚钓鱼竿。","觉来不忍轻开眼，窗外芭蕉战晓寒。"]},{"t":"泊吴江塔院喜霁","f":"七言律诗","c":["风雨因何犯晓来，不教閒却好诗材。","直须船内幽人起，始放天边暖日开。","杰阁岂容关一面，长桥浑欲走千回。","归时相见逢佳月，忙杀同行鹦鹉杯。"]},{"t":"表兄刘东玉提干挽诗二首 其二","f":"五言律诗","c":["襁褓予多疾，三年托渭阳。","未能看击瓮，常是戏登床。","转首尘埃里，惊心岁月长。","挽兄赍志去，倾泪入诗章。"]},{"t":"表兄刘东玉提干挽诗二首 其一","f":"五言律诗","c":["王祖扶天日，同声外氏翁。","功勋俱卓越，门户合穹隆。","诸舅今何在，唯兄命亦穷。","贤郎须力学，一线续家风。"]},{"t":"诗本","f":"五言律诗","c":["诗本无心作，君看蚀本虫。","旁人无鼻孔，我辈岂神通。","风雅难齐驾，心胸未发蒙。","吾虽知此理，恐堕见闻中。"]},{"t":"诚斋以南海朝天两集诗见惠因书卷末","f":"七言律诗","c":["笔端有口古来稀，妙悟奚烦用力追。","南纪山川题欲遍，中朝文物写无遗。","后山格律非穷苦，白傅风流造坦夷。","霜鬓未闻登翰苑，缓公高步或因诗。"]},{"t":"诚斋再韵见遗走笔复和并邀尤检正京右司观花","f":"词","c":["要趁清霜未染林，小山同赏桂丛深。","巳?醉后缠头锦，莫待风前布地金。","兰桨溯流歌客棹，麝材匀捣付香砧。","戈挥就借如椽笔，不信湖边日易沉。"]},{"t":"述兴","f":"七言律诗","c":["履声几月到园稀，雪后烟香特地宜。","巳见新晴巢喜鹊，更添垂柳客黄鹂。","人来有话亦大好，酒不酬春奚以为。","今日正晴休怕冷，笑中天地角巾欹。"]},{"t":"雨中忆昙少云奉寄","f":"七言律诗","c":["天意今年不惜凉，雨声秋后恣淋浪。","单衣巳觉生絺薄，细字初便短烛光。","画饼功名孤塞路，守株身世老江乡。","吾侪政要无人识，黄叶深林气味长。"]},{"t":"雨中约梅再赋","f":"七言律诗","c":["寄语堂前万玉枝，未须开尽等人归。","行云佩杂衣从湿，溅水裙轻步自微。","关塞垂杨横槊赋，禁津芳草掞毫挥。","为君岂复仍关念，看到清阴碧实肥。"]},{"t":"侵晨飞霰薄暮雪未成","f":"七言律诗","c":["呃喔花冠梦易呼，冻天应遍色模糊。","旋听索索敲松瓦，便拟翩翩傍酒觚。","一白要从高砌看，双清先喜小山俱。","晚檐坐断违消息，待问林深寺有无。"]},{"t":"南湖二亭落成各书长句一首 其一 野芳","f":"七言律诗","c":["望处阴云纵复横，落梅那更两关情。","清愁入梦时飞蝶，远树和烟欲啭莺。","多病半春诗债满，经旬无客酒缘轻。","湖亭记取初成日，正是菖蒲斫水生。"]},{"t":"南湖夕泛","f":"七言律诗","c":["欲知家住画图中，静向波心漾短篷。","粉墨晕开天水色，碧朱堆上柳花丛。","云边鸥影来还去，篱畔鸡声西复东。","别浦夷犹岂无谓，细看蘋末受清风。"]},{"t":"南湖书斋","f":"七言律诗","c":["雨深愁入树花飘，尽际翻晴现帝霄。","目力壮时苍岫长，心情閒处戏鱼跳。","秋云总是诗家物，夜市今连里陌桥。","船子不来同载我，却惊翡翠出兰苕。"]},{"t":"南湖有怀遂初尤公侍郎寄赠七言","f":"七言律诗","c":["停骖曾送柳边舟，忽忽今冬病故秋。","望远溪山常入梦，写残书信只成愁。","明心坐断三千佛，谒帝行归十二楼。","临水忆君谁复信，乱烟凄暮白芦洲。"]},{"t":"客有折秋香来桂隐者喜成七言呈以道","f":"七言律诗","c":["半纪移居野水旁，年年尝为木樨忙。","若非老树从头发，安得西风彻骨香。","数朵折来犹甚爱，满林开后得无狂。","今番莫把寻常比，一段清香两主张。"]},{"t":"客至","f":"七言律诗","c":["麝萱沿径绿抽牙，文杏飘蹊白覆沙。","过半春光须爱惜，沓来人事费拦遮。","妨寻蚁径看排阵，阻向蜂筒听报衙。","癖性杜门犹惮此，刺头尘土可堪嗟。"]},{"t":"客舍夜闻吴讴有怀南湖","f":"五言律诗","c":["屋漏灯垂粟，墙欹螾唱丛。","断编非径捷，隅座且丞聋。","歌听鱼蛮子，盟寒水勃公。","月明今夜梦，清杀苇间篷。"]},{"t":"徇俗","f":"五言律诗","c":["徇俗非能事，便幽定宿缘。","跃泉新作雨，装树巧留烟。","雀喜频频下，蜂知小小穿。","疏风奏檐佩，无梦到钧天。"]},{"t":"春分后一日山堂述事 其一","f":"七言律诗","c":["永日柴扉手自关，不惊时序若循环。","鍊成黄土为真药，守得青苔遍假山。","戊巳燕知随鸟历，西南樱喜趁花斑。","春光莫恨中分过，能使时长始是閒。"]},{"t":"春分后一日山堂述事 其三","f":"七言律诗","c":["老圃工夫愈可嘉，种藤萦树尽开花。","人间似我能閒少，石上看云到日斜。","樵径有苔休埽叶，茅庵无客亦煎茶。","两边最喜添新竹，夕照斜时渐可遮。"]},{"t":"春分后一日山堂述事 其二","f":"七言律诗","c":["每到山堂懒作诗，今朝诗兴觉偏宜。","层林飒遝阴填户，乱石巃嵷翠绕池。","猛欲近前闻紫燕，忽听高处啭黄鹂。","风铃不必檐间语，境界非凡我熟知。"]},{"t":"春分后一日山堂述事 其四","f":"七言律诗","c":["岩通道院碧桃妍，别号琅华小洞天。","香火微官方称职，轩裳閒梦自无缘。","星坛夜礼魁罡列，丹室朝存震兑全。","绝粒飞升休慢语，不求人已是神仙。"]},{"t":"春在","f":"五言律诗","c":["春在将回暑，晴开尚带阴。","佳时从易过，閒日尽能禁。","卧室宜重立，浮鱼乐又沉。","有诗无亦好，争似有时心。"]},{"t":"春前一日赋呈诚斋觅荆溪诗编且邀看玉照堂花","f":"五言律诗","c":["颇讶蓬莱主，相忘不寄诗。","荆溪虽有集，桂隐未容窥。","地胜人难老，春回律自移。","梅花如有语，莫似去年时。"]},{"t":"春晚","f":"五言律诗","c":["湖远慵呼艇，春归只闭门。","树高应翠合，竹静自黄昏。","轩冕情终薄，诗书好益尊。","人间难办事，夜气要长存。"]},{"t":"春晴独坐次叔祖阁学韵","f":"七言律诗","c":["䰐鬖绿柳拂垣衣，课蜜蜂忙踏蕊归。","须趁一春随意适，极知万事转头非。","添垆麝饼遮残火，拥案尘编绝故韦。","便当清欢忘肉味，况安淡泊少甘肥。"]},{"t":"昼寒一杯辄欲酩酊因静坐道室","f":"七言律诗","c":["岁晏常多白昼阴，软帘毡帐禦寒侵。","观书偶要得天隐，作传定难题醉吟。","犬吠远闻风绰散，叶凋谁顾雨堆深。","湖边莫道春回未，紫草依稀动绝岑。"]},{"t":"皇太子生辰二首 其一","f":"七言律诗","c":["无射吹铜恰四蓂，紫微深处粲前星。","木行袭庆联三合，火德流光共一丁。","玩鹤怡神资葆毓，闻鸡为善想仪刑。","丰年在在歌华黍，鸿鹄高飞万宇宁。"]},{"t":"秋日登集仙台","f":"七言律诗","c":["地荒无处可追游，赖有兹山景颇幽。","远水一隅横雪练，乔松千丈舞云虬。","飘飖霞想生来避，胶扰尘心老更休。","不向是中观月去，城中那可度中秋。"]},{"t":"秋风","f":"七言律诗","c":["策策惊飙战素秋，梦回衾幔亦飕飗。","不传鸿雁秦关信，可柰蘋蘅楚客愁。","作赋未须悲落木，挂帆方喜助归舟。","何须更借抟扶便，自是层霄九万游。"]},{"t":"秋声","f":"七言律诗","c":["林居多解识秋声，岂是松篁耳惯经。","桐杂蝉鸣愁易起，蕉和蛬响梦频醒。","琅琅急雨喧荷港，戛戛清风战苇亭。","一事古人犹可恨，不言杨柳最堪听。"]},{"t":"秋暖","f":"七言律诗","c":["秋暖浑如水上春，意行幽径散衣巾。","海棠突过色尤好，荷叶打空芽更新。","焉得便遭田父饮，不须真现宰官身。","今朝涉趣初悬榜，争睹何妨走四邻。"]},{"t":"种蜡梅喜成时欲暂往梁溪","f":"七言律诗","c":["出得荆扉喜欲颠，园夫撑到蜡梅船。","包封山土根微脱，束缚溪藤叶尚鲜。","搬处侧从新径里，种时围向旧台边。","叮咛等待吾归看，切莫开花小至前。"]},{"t":"送叶正则秘郎参议湖北帅幕","f":"五言律诗","c":["桂隐无期报，朝贤去却知。","累年艰特荐，一事必忧时。","盛世未应尔，重来犹可为。","相过非为数，公论合勤思。"]},{"t":"送叶景良知严陵","f":"七言律诗","c":["千古风高仰钓台，朱轮新拥得通才。","政声易报长安近，家学知从霅水来。","半载依仁方恨别，双鱼传信肯慵开。","分携强饭休频祝，锋召需贤定挽回。"]},{"t":"送京仲远次对制帅四川 其三","f":"五言律诗","c":["贱子夫谁问，鸣驺屡水湄。","自因闲肯顾，不是佞求知。","山槛清持茗，花蹊笑说诗。","雨风今送别，悽断湿旌旗。"]},{"t":"送京仲远次对制帅四川 其一","f":"五言律诗","c":["林下忘官品，闻公近最荣。","军民制全蜀，名住列西清。","器自海岳重，文兼全玉声。","早来登政府，活法了寰瀛。"]},{"t":"送京仲远次对制帅四川 其二","f":"五言律诗","c":["使北人争说，今回国势尊。","属声坚执礼，黠虏殆忘魂。","钜业此犹细，故强行复存。","乡闾正关外，因梦逐西辕。"]},{"t":"送郑刚中赴江东参议","f":"七言律诗","c":["去程遥指石头城，秋与钟山老气清。","紬绎蓬峦曾正字，参陪莲幕试论兵。","时平得计甘微禄，学古无心急近荣。","君岂江淮久游客，归来矍铄上承明。"]},{"t":"送赵季言知抚州","f":"七言律诗","c":["同寅心契每难忘，林野投閒话最长。","自是文华兼政术，非徒神秀出天潢。","临岐暂送鱼符客，指日归来画省郎。","诗社不应常寂寞，赖君搜奖出江乡。"]},{"t":"送徐衡仲归侍次福建帅属二首 其二","f":"七言律诗","c":["和篇犹未忽成行，无柰离情杂愧情。","风雨连朝难远送，湖山何日再寻盟。","饱参屡见从头举，识破悬知到处轻。","疏懒祗愁书问少，望君因便却传声。"]},{"t":"送徐衡仲归侍次福建帅属二首 其一","f":"七言律诗","c":["三年林曲喜谈丛，交荐俄闻得数公。","竟觅一官莲幕下，漫添千咏锦囊中。","时乖岂但冯唐老，性癖甘如叔夜慵。","应是黄花过江路，笑垂双袖立西风。"]},{"t":"送喻叔奇工部括苍二首 其二","f":"五言律诗","c":["自复林湖隐，相从却恨稀。","梅花年后白，江水去边肥。","世态纷纷改，交心特特违。","暖晴当送别，敢望款柴扉。"]},{"t":"送喻叔奇工部括苍二首 其一","f":"五言律诗","c":["三见中朝入，徐行每后人。","功庸身较晚，名誉众常新。","有句须同咏，今离似所亲。","政成应必报，山郡易回春。"]},{"t":"送谢艮斋得閒西归","f":"七言律诗","c":["向来朝列虽知己，台省山林职事殊。","勇退近闻辞北阙，醉游唯欠到南湖。","心传古学高当代，力把忠言壮晚途。","竞说归舟卖金带，囊空想见一钱无。"]},{"t":"送鹤还建康章德茂侍郎因成两诗 其二","f":"七言律诗","c":["风仪不称汨泥尘，清向亨衢快举身。","鱼钥麟符行作伴，鹭洲燕巷得为邻。","华亭清唳如前日，蜀道高风过昔人。","他日侍郎登凤沼，却来湖畔静怡神。"]},{"t":"重九前一日领客登城即席次张以道韵","f":"七言律诗","c":["未倒花前凿落金，登携那怕嫩寒侵。","归牛下陇争浮水，宿鸟随山不过林。","衰鬓预吹明日帽，放歌时带故园音。","菊烟桂露虽情物，须索高蟾管夜深。"]},{"t":"重五日不饮偶成长句","f":"七言律诗","c":["林墅光阴日日新，不因时节强随人。","青红雨砌戎葵柳，金玉风池荇菜蘋。","千载是非均似梦，一朝醒醉肯沈身。","綵丝菖歜喧儿女，谁信清吟兴独真。"]},{"t":"重过凤山高氏","f":"五言律诗","c":["屋负山陲晚，篱侵水泺秋。","农桑能自力，鹅鸭岂它求。","逆数曾来日，遮留更觉稠。","夜歌听欸乃，催兴满沧洲。"]},{"t":"挽叔祖户部侍郎诗四首 其四","f":"五言律诗","c":["内典存心久，家居戒行僧。","同尘聊且尔，著相亦何曾。","脱却当来裤，传将不尽灯。","欲知归甚处，一月万波澄。"]},{"t":"挽叔祖户部侍郎诗四首 其三","f":"五言律诗","c":["小小为知己，常常说向人。","论情宗族异，问事见闻新。","囊锦将谁管，湖园看未真。","伤心啸庵路，不复送亲宾。"]},{"t":"挽叔祖户部侍郎诗四首 其二","f":"五言律诗","c":["八郡恢成绩，江山入壮图。","风流羊叔子，才术管夷吾。","绝笔诗犹在，酬君志不渝。","经纶如有位，肯堕浅规摹。"]},{"t":"挽叔祖户部侍郎诗四首 其一","f":"五言律诗","c":["从此无因见，南园老叔翁。","朝廷世臣少，文献我家穷。","达宦谁无分，全材不易逢。","先王勋第一，号恸仰天公。"]},{"t":"晓出海会过新溪渡","f":"七言律诗","c":["喧喧人语俶行装，广殿灯寒暗古廊。","桥截漫滩收夜色，路经层岫吐朝阳。","鳞差白石中流见，栉比篬筠夹坞香。","爽气正浓诗兴薄，归途应愧挈空囊。"]},{"t":"晓探晴观梅","f":"七言律诗","c":["天鸡催日界窗横，蹑屐看花兴便成。","正尔飞霞舒綵佩，尽渠宿雨结珠缨。","飘零未带溪边笛，缥缈如临海上城。","身世长吟谁会得，华祠梅市总逃名。"]},{"t":"晓寝喜成","f":"七言律诗","c":["人间一事最幽奇，病醉皆非半睡时。","经纸屏低心正惬，木绵衾暖足慵移。","蘧蘧蝶梦萦孤枕，呃呃鸡声过短篱。","无奈冲寒早朝客，不知疏拙是便宜。"]},{"t":"桂树下作","f":"词","c":["芳桂年年种，今秋两倍开。","略无蜂敢傍，为是月中来。","幸自晴多日，须?醉几回。","便教香杀了，犹胜别人呆。"]},{"t":"桂隐花正开得诚斋木樨七言次韵奉酬","f":"七言律诗","c":["未说香高众卉林，清名先巳入人深。","衣青萼绿不见佩，屋贮阿娇纯用金。","久恨酒肠悭似盏，更输诗字响如砧。","公能为办归休计，肯向花前叹陆沉。"]},{"t":"桃花","f":"五言律诗","c":["园翁能好客，折赠小春桃。","却为开花少，翻成占格高。","来年红烂漫，绕涧碧周遭。","莫忘阊门外，曾将进浊醪。"]},{"t":"烟波观月示客","f":"七言律诗","c":["半年殊少夜间来，湖上今宵绝点埃。","人老纵教过百岁，月圆难保看千回。","舒眉酒饮休辞满，冲口诗成不待催。","自有一般堪乐处，却言山水近亭台。"]}]};